/* lookup set token (P2bis: niente if-chain di catalogo). */
static int gmb_tk_in(gmb_tokenkind_t tk, const gmb_tokenkind_t* s, unsigned n)
{
    for (unsigned i = 0; i < n; i++) if (s[i] == tk) return 1;
    return 0;
}
