/* Campo di classe con tipo di COLLEZIONE (testo del tipo: "LIST OF X" oppure token List):
 * punto UNICO di risoluzione del tipo-list per i campi (via token, senza strncasecmp duplicati
 * e senza from_name ripetuti per ogni campo). */
static int gmb_ctype_is_list(const char* t)
{
    if (!t) return 0;
    if (strncasecmp(t, "LIST OF ", 8) == 0) return 1;
    return strcasecmp(t, "LIST") == 0;
}
/* Nome del tipo elemento di "LIST OF X" (X), "" altrimenti. */
static const char* gmb_list_elem_of(const char* t)
{
    static char buf[64]; const char* p; int i = 0;
    if (!t || strncasecmp(t, "LIST OF ", 8) != 0) return "";
    p = t + 8;
    while (*p && *p != ' ' && *p != '<' && *p != '>' && i < 63) buf[i++] = *p++;
    buf[i] = 0;
    return buf;
}



/* gmb_ns_type_is_str: 1 se la funzione col DispatchToken dato ritorna StringType
 * (tabella generata dal registro StdLib — gmb_ns_types.h, VALORI enum: confronto
 * token==token, nessuna risoluzione per nome). */
static int gmb_ns_type_is_str(gmb_tokenkind_t tk)
{
    if ((int)tk <= 0) return 0;
    for (int i = 0; i < GMB_NS_TYPES_COUNT; i++)
        if (gmb_ns_types[i].tk == tk) return gmb_ns_types[i].is_str;
    return 0;
}

/* ─────────────────────────── string buffer ─────────────────────────── */

typedef struct { char* s; size_t len, cap; } sb_t;

static void sb_putn(sb_t* b, const char* s, size_t n) {
    if (b->len + n + 1 > b->cap) {
        size_t nc = b->cap ? b->cap * 2 : 4096;
        while (nc < b->len + n + 1) nc *= 2;
        b->s = (char*)realloc(b->s, nc);
        b->cap = nc;
    }
    memcpy(b->s + b->len, s, n);
    b->len += n;
    b->s[b->len] = 0;
}
void sb_put(sb_t* b, const char* s) { sb_putn(b, s, strlen(s)); }
void sb_printf(sb_t* b, const char* fmt, ...) {
    char tmp[1024];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(tmp, sizeof(tmp), fmt, ap);
    va_end(ap);
    if (n > 0) sb_putn(b, tmp, (size_t)n);
}
/* Inserisce testo in una posizione già emessa (memmove). Serve alle dichiarazioni
 * `jmp_buf __errN` degli handler ON ERROR: devono vivere nello scope della FUNZIONE
 * (il puntatore registrato in gmb_err_set_handler resta attivo fino a fine procedura),
 * quindi vengono inserite a posteriori nel prologo — vedi err_decl_insert. */
static void sb_insert(sb_t* b, size_t pos, const char* s, size_t n) {
    if (pos > b->len) pos = b->len;
    if (b->len + n + 1 > b->cap) {
        size_t nc = b->cap ? b->cap * 2 : 4096;
        while (nc < b->len + n + 1) nc *= 2;
        b->s = (char*)realloc(b->s, nc);
        b->cap = nc;
    }
    memmove(b->s + pos + n, b->s + pos, b->len - pos);
    memcpy(b->s + pos, s, n);
    b->len += n;
    b->s[b->len] = 0;
}

/* ────────────────────────────── tipi ───────────────────────────────── */

enum { TY_NUM = 0, TY_STR = 1, TY_VAL = 2 };   /* TY_VAL: tipo dinamico (numero/stringa a runtime) */

/* FASE 2.6(b): variabili oggetto di sincronizzazione GPM (DIM AS CHANNEL/...) */
enum { GK_PLAIN = 0, GK_CHAN, GK_WG, GK_MUTEX, GK_RWMUTEX, GK_ONCE, GK_COND,
       GK_ATOMIC, GK_POOL, GK_SYNCMAP, GK_CONTEXT, GK_HTTPREQ, GK_HTTPRESP, GK_WEBSOCKET,
       GK_FUNCVAL /* DIM v AS FUNCTION(...)/SUB(...): valore funzione di prima classe (gmb_fn_t) */,
       GK_GEN     /* DIM it = <Generatore>(args): oggetto generatore (struct gmb_gen_<id>_t) */,
       GK_LIST,   /* collections: DIM v AS LIST<...> (gmb_list_t per valore) */
       GK_DICT,   /* collections: DIM v AS DICT<...> (gmb_dict_t per valore) */
       GK_QUEUE,  /* QUEUE (FIFO) → gmb_list_t + push enqueue/dequeue */
       GK_STACK,  /* STACK (LIFO) → gmb_list_t + push/pop */
       GK_SET,    /* HASHSET (unici) → gmb_list_t, dedup all'add/literal */
       GK_SORTED, /* SORTED (dizionario ordinato) → gmb_dict_t, Keys() ordinata */
       GK_GRAPH,  /* GRAPH → handle int64_t del runtime condiviso gmb_graph_* (stesso
                   * registry del VM/C GMB_OBJ_GRAPH, §0bis: una sola implementazione) */
       GK_MATRIX  /* MATRIX handle → int64_t del runtime gmb_matrix_* (MATRIX.CREATE/…) */ };
static int gk_is_list(int gk) { return gk == GK_LIST || gk == GK_QUEUE || gk == GK_STACK || gk == GK_SET; }

/* TokenKind dei builtin che ritornano una LISTA: la variabile che li riceve va tipata
 * gkind=GK_LIST, altrimenti per l'emitter non e' una lista e UBOUND(v)/v(i) falliscono
 * (bd_ubound pretende is_array; il ramo UBOUND(lista) pretende gkind; la subscript di una
 * variabile non-lista viene letta come CHIAMATA a funzione). *elem_str: 1 = lista di stringhe.
 * Prima l'inferenza esisteva SOLO per la forma assegnazione e SOLO per IO.DIR. */
static int tk_returns_list(gmb_tokenkind_t tk, int* elem_str) {
    switch (tk) {
        case GMB_TOK_DirFunc:
        case GMB_TOK_ReadLinesFunc: *elem_str = 1; return 1;
        case GMB_TOK_ReadBytesFunc: *elem_str = 0; return 1;
        /* FONTS (TrueType/OpenType): le tre funzioni ritornano gmb_list_t dal runtime
         * condiviso (bitmap di byte; metriche e codepoint come numeri). */
        case GMB_TOK_TtRenderFunc: *elem_str = 0; return 1;
        case GMB_TOK_TtMetricsFunc: *elem_str = 0; return 1;
        case GMB_TOK_TtGlyphsFunc: *elem_str = 0; return 1;
        /* Metodi DICT che ritornano gmb_list_t: `DIM vs = d.Values()` senza questa inferenza
         * veniva dichiarata numerica → assegnazione di gmb_list_t a double (errore cc). */
        case GMB_TOK_Keys: *elem_str = 1; return 1;
        case GMB_TOK_Values: *elem_str = 0; return 1;
        /* AI.LIST(role): gmb_list_t di stringhe (parità string[] C#) — `DIM x() = AI.LIST(..)`. */
        case GMB_TOK_AiList: *elem_str = 1; return 1;
        /* AI.AGENTLIST()/AI.AGENTEVENTS(): string[] (C#) → gmb_list_t di stringhe
         * (gmb_agent_list_names / gmb_agent_events_names). */
        case GMB_TOK_AiAgentList: *elem_str = 1; return 1;
        case GMB_TOK_AiAgentEvents: *elem_str = 1; return 1;
        case GMB_TOK_Range: *elem_str = 0; return 1;
        case GMB_TOK_MemoryMapReadBytes: *elem_str = 0; return 1;
        /* F5 multimodale (2026-09-11): AI.IMAGEEMBED → gmb_list_t (64 double).
         * AI.EMBED → lista double (gmb_list_from_double_array). */
        case GMB_TOK_AiImageEmbed: *elem_str = 0; return 1;
        case GMB_TOK_AiVectorEmbed: *elem_str = 0; return 1;
        /* G10: SQL.COL(rs, col) → gmb_list_t (colonna intera; valori resi stringa per il
         * path DIM-lista condiviso, parità di OUTPUT con IL/PCode/VM-C). */
        case GMB_TOK_SqlCol: *elem_str = 1; return 1;
        /* CONVERT.* Markdown AST list-returning (gmb_val_t boxed → gmb_val_as_list, che
         * l'handler emit_bf_convert emette): elementi gmb_val_t (dict), non double/string. */
        case GMB_TOK_MdHeadings: case GMB_TOK_MdLinks: case GMB_TOK_MdImages:
        case GMB_TOK_MdTables: case GMB_TOK_MdCodeBlocks: case GMB_TOK_MdQuery:
            *elem_str = 0; return 1;
        default: return 0;
    }
}
/* CONVERT.* Markdown AST che ritornano una LISTA boxed (elementi gmb_val_t dict). */
/* Esposta a gmb_c99_emit_builtin.c (TU separata): `UBOUND(<call>)` per OGNI builtin che ritorna lista. */
int gmb_c99_tk_returns_list(gmb_tokenkind_t tk) { int es = 0; return tk_returns_list(tk, &es); }
static int tk_is_md_list(gmb_tokenkind_t tk) {
    return tk == GMB_TOK_MdHeadings || tk == GMB_TOK_MdLinks || tk == GMB_TOK_MdImages
        || tk == GMB_TOK_MdTables || tk == GMB_TOK_MdCodeBlocks || tk == GMB_TOK_MdQuery;
}
static int gk_is_dict(int gk) { return gk == GK_DICT || gk == GK_SORTED; }

/* gkind → typeCode BASIC della collezione (stessa mappa del compilatore/VM-C:
 * gmb_collection_type_name/valtype_letter). 0 = non è una collezione. */
static int gk_to_type_code(int gk) {
    switch (gk) {
        case GK_LIST: return 1;
        case GK_DICT: return 2;
        case GK_SET: return 3;
        case GK_QUEUE: return 4;
        case GK_STACK: return 5;
        case GK_SORTED: return 6;
        case GK_GRAPH: return 17;
        default: return 0;
    }
}

/* Letterale array: il parser rappresenta { e1, ..., en } come CALL "_array_". */
static int is_array_literal(const gmb_expr_t* e) {
    return e && e->kind == GMB_EXPR_CALL && e->var && strcmp(e->var, "_array_") == 0;
}
/* Letterale ANNIDATO {{...}}: ogni elemento è a sua volta un letterale array.
 * Rappresentato come gmb_list_t di sotto-liste (parity IL: UBOUND=righe, AFLAT appiattisce). */
static int is_nested_array_literal(const gmb_expr_t* e) {
    if (!is_array_literal(e) || e->nargs == 0) return 0;
    for (int i = 0; i < e->nargs; i++) if (!is_array_literal(e->args[i])) return 0;
    return 1;
}


typedef struct fn_info {
    gmb_stmt_t* stmt;          /* nodo GMB_STMT_FUNCTION (non posseduto) */
    vars_t locals;             /* parametri + variabili locali */
    int n_params;
    gmb_stmt_t** defers; int n_defers, defer_cap;   /* DEFER registrati (LIFO all'uscita) */
    char* go_wrap;               /* wrapper GO SUB senza waitgroup (generato una volta) */
    char* go_wrap_wg;            /* wrapper GO SUB con IN wg (generato una volta) */
    char* go_wrap_fn;            /* wrapper GO FUNCTION ... INTO (future, generato una volta) */
    char* http_wrap;             /* 2.6(p): wrapper handler HTTP route→SUB (generato una volta) */
    char* http_mw_wrap;          /* HTTP USE: wrapper middleware (generato una volta, distinto
                                  * dal route-wrap perché arma gmb_http_set_current_step e
                                  * passa lo step-id al posto del ws-val come 3° arg). */
    char* ws_msg_wrap;           /* 2.6(q): wrapper dispatch messaggio WS→SUB OnMessage/OnError (una volta) */
    int err_raise;               /* ERROR nel body SOLLEVA sempre (gmb_raise_error): il body è
                                  * eseguito dentro un wrapper GO FUNCTION con setjmp che lo
                                  * cattura → future in errore (frame propagation) */
    struct fn_info* parent;      /* FASE 2.6(j): funzione nidificata → funzione contenitore */
    int parent_i;                /* indice del contenitore (stabile tra realloc): per le λ
                                  * sintetiche il parent non è cercabile nel body — usato da
                                  * repair_parents. -1 = non impostato. */
    int n_cap;                   /* FASE 2.6(j): variabili catturate (locals con captured=1) */
    int is_lambda_cap;           /* 2026-09-03: λ con catture by-value (ctx __lctx_<nome>
                                  * allocato+inizializzato al reference) — i campi catturati
                                  * sono in locals con captured=1 */
    int is_lambda;               /* 2026-09-03: funzione sintetica da una λ → firma con
                                  * `void* __ctx` PRIMO parametro (il valore è sempre chiamato
                                  * via gmb_fn_t con ctx, anche se non cattura nulla) */
    int lambda_ret_arr_len;      /* λ che ritorna {..}: numero di residui/equazioni (m) */
    int has_gosub;               /* 2.6(s): body con siti GOSUB → RETURN con dispatch stack */
    char cls_owner[40];          /* 2.7: metodo di classe → firma con gmb_val_t* self */
    int ovl_idx;                 /* 2026-09-24 (overload): indice omonimo (0 = nome C nudo
                                  * gmb_user_<nome>, >0 = suffisso __N). Assegnato da
                                  * assign_cnames per le top-level senza cls_owner. */
} fn_info_t;

