void gmb_c99_emit_dyn_declare(ctx_t* c, gmb_stmt_t* s);
int  gmb_c99_try_emit_dyn_read(ctx_t* c, const char* name);
int  gmb_c99_try_emit_dyn_write(ctx_t* c, const char* target, gmb_expr_t* value);

/* ── jmp_buf degli handler ON ERROR: scope di FUNZIONE, non di blocco ─────────────
 * `gmb_err_set_handler` conserva solo il PUNTATORE al jmp_buf: dichiararlo in un blocco
 * che termina subito (come faceva l'emissione `{ jmp_buf __errN; … }`) lo lascia
 * dangling — al longjmp lo slot può essere stato riusato → salto a indirizzo garbage
 * (SIGSEGV/SIGBUS) o loop di longjmp. Al sito si REGISTRA l'ID; la dichiarazione
 * `jmp_buf __errN;` viene INSERITA nel prologo della funzione dopo l'emissione del
 * corpo (sb_insert). Vedi Bugs/(open) - C99-ON-ERROR-jmpbuf-Fuori-Scope.md. */
static void err_decl_record(ctx_t* c, int id) {
    if (c->n_err_decl < 64) c->err_decl_ids[c->n_err_decl++] = id;
}
static void err_decl_insert(ctx_t* c, int sv, size_t pos) {
    for (int k = sv; k < c->n_err_decl; k++) {
        char line[64];
        int n = snprintf(line, sizeof line, "    jmp_buf __err%d;\n", c->err_decl_ids[k]);
        if (n > 0) sb_insert(&c->out, pos, line, (size_t)n);
    }
    c->n_err_decl = sv;
}

/* ── O8: anchor file/riga del sorgente concatenato ────────────────────────────────────────
 * Compilati da gmb_c99_set_source_anchors (vedi gmb_c99_emit.h). Servono due volte:
 *  - `c99_fail` per dire in quale `.bas`/`.inc` sta la riga dell'errore di emissione;
 *  - `emit_src_line` per i `#line` del C generato. */
static const gmb_c99_anchor_t* g_c99_anchors = NULL;
static int g_c99_nanchors = 0;
static int g_c99_last_dir_line = -1;
static char g_c99_last_dir_file[4096] = "";

static int c99_src_locate(int line, const char** file, int* file_line) {
    if (line <= 0) return 0;
    for (int i = g_c99_nanchors - 1; i >= 0; i--) {
        if (g_c99_anchors[i].line > 0 && g_c99_anchors[i].line <= line
            && g_c99_anchors[i].file && g_c99_anchors[i].file[0]) {
            if (file) *file = g_c99_anchors[i].file;
            if (file_line) *file_line = 1 + (line - g_c99_anchors[i].line);
            return 1;
        }
    }
    return 0;
}

void gmb_c99_set_source_anchors(const gmb_c99_anchor_t* anchors, int n) {
    g_c99_anchors = anchors;
    g_c99_nanchors = n > 0 ? n : 0;
    g_c99_last_dir_line = -1;
    g_c99_last_dir_file[0] = 0;
}

void c99_fail(ctx_t* c, int line, const char* fmt, ...) {
    if (c->error[0]) return;
    va_list ap;
    va_start(ap, fmt);
    char msg[448];
    vsnprintf(msg, sizeof(msg), fmt, ap);
    va_end(ap);
    const char* file = NULL;
    int fline = line;
    /* Con la mappa attiva il messaggio cita il sorgente originale (file:riga); senza
     * mappa resta il formato storico `riga N` usato dagli harness. */
    if (c99_src_locate(line, &file, &fline) && file)
        snprintf(c->error, sizeof(c->error), "%s:%d: %s", file, fline, msg);
    else
        snprintf(c->error, sizeof(c->error), "riga %d: %s", line, msg);
}
#define CHK() if (c->error[0]) return
#define CHKV(v) if (c->error[0]) return (v)

/* Normalizza un nome-variabile BASIC: i suffissi di tipo ($ % ! # &) NON fanno parte del nome
 * — il C# equa `X#`=`X` (il suffisso è solo il tipo). Strip dell'ULTIMO suffisso in `buf`. */
static const char* norm_var(const char* name, char* buf, size_t cap) {
    size_t l = name ? strlen(name) : 0;
    if (l > 1 && (name[l-1]=='$'||name[l-1]=='%'||name[l-1]=='!'||name[l-1]=='#'||name[l-1]=='&')) {
        size_t c = (l-1 < cap-1) ? l-1 : cap-1;
        memcpy(buf, name, c); buf[c] = 0;
        return buf;
    }
    return name;
}
/* Non-static: condivisa con gmb_c99_emit_speed.c (§0quater). */
var_t* vars_find(vars_t* v, const char* name) {
    if (!name) return NULL;
    char nb[160]; const char* nn = norm_var(name, nb, sizeof nb);
    for (int i = 0; i < v->n; i++) {
        char vb[160]; const char* vn = norm_var(v->v[i].name, vb, sizeof vb);
        if (strcasecmp(vn, nn) == 0) return &v->v[i];
    }
    return NULL;
}
var_t* vars_add(vars_t* v, const char* name, int type) {
    var_t* e = vars_find(v, name);
    if (e) return e;
    if (v->n >= v->cap) {
        v->cap = v->cap ? v->cap * 2 : 16;
        v->v = (var_t*)realloc(v->v, (size_t)v->cap * sizeof(var_t));
    }
    v->v[v->n].name = strdup(name);
    v->v[v->n].type = type;
    /* Lo slot dopo realloc contiene GARBAGE: azzerare TUTTO (un campo non
     * inizializzato — es. jagged/matrix_handle — rende l'emissione dipendente
     * dal contenuto dell'heap). */
    memset(&v->v[v->n], 0, sizeof(var_t));
    v->v[v->n].name = strdup(name);
    v->v[v->n].type = type;
    v->v[v->n].is_array = 0;
    v->v[v->n].ndims = 0;
    v->v[v->n].byref = 0;
    v->v[v->n].gkind = GK_PLAIN;
    v->v[v->n].elem_str = 0;
    v->v[v->n].elem_class[0] = 0;
    v->v[v->n].captured = 0;
    v->v[v->n].cap_ref = 0;
    v->v[v->n].dyn_len = 0;
    v->v[v->n].matrix = 0;
    v->v[v->n].boxed_val = 0;
    v->v[v->n].rgba_obj = 0;
    v->v[v->n].stats_val = 0;
    v->v[v->n].ring_cap = 0;
    v->v[v->n].fixed_len = 0;
    v->v[v->n].arr_byref = 0;
    v->v[v->n].vclass[0] = 0;
    v->v[v->n].implicit_alloc = 0;
    return &v->v[v->n++];
}

/* Suffisso BASIC: '$' → stringa. '%' (intero) emesso come double in FASE 1. */
static int suffix_type(const char* name) {
    size_t l = strlen(name);
    if (l > 0 && name[l - 1] == '$') return TY_STR;
    return TY_NUM;
}

/* scope corrente: locali della funzione corrente, altrimenti globali */
vars_t* cur_scope(ctx_t* c) { return c->cur_fn ? &c->cur_fn->locals : &c->globals; }

var_t* lookup_var(ctx_t* c, const char* name) {
    if (!name) return NULL;
    if (c->cur_fn) {
        var_t* v = vars_find(&c->cur_fn->locals, name);
        if (v && !v->late_local) return v;
    }
    return vars_find(&c->globals, name);
}

static void dbf_field_imap_ensure(ctx_t* c, const char* name);
/* Variante per un RECORD VAR `<var>.<campo>`: la chiave imap è il nome QUALIFICATO, ma
 * l'espressione area-aware usa solo il CAMPO (il record var è la vista del record corrente). */
static void dbf_field_imap_ensure_as(ctx_t* c, const char* key, const char* field) {
    char dx[256];
    if (!key || !*key || !field || !*field) return;
    for (int i = 0; i < c->n_imap; i++)
        if (strcasecmp(c->imap_name[i], key) == 0) return;
    if (c->n_imap >= 32) return;
    snprintf(dx, sizeof(dx),
             "(gmb_db_current_dbf() > 0 ? gmb_db_dbf_field_val_name(gmb_db_current_dbf(), \"%s\") : gmb_rdd_get_field_str_name(\"%s\"))",
             field, field);
    c->imap_name[c->n_imap] = (char*)key;
    c->imap_expr[c->n_imap] = strdup(dx);
    c->n_imap++;
}

/* DBF GET <var>: registra <var> come RECORD VAR (vista del record corrente). Niente codice
 * emesso: `<var>.<campo>` viene risolto in `ensure_dbf_field_var` come campo late-bound. */
static void dbf_recvar_add(ctx_t* c, const char* name) {
    if (!name || !*name || strchr(name, '.')) return;
    for (int i = 0; i < c->n_recvar; i++) if (strcasecmp(c->recvar_name[i], name) == 0) return;
    if (c->n_recvar < 16) c->recvar_name[c->n_recvar++] = name;
}
static int dbf_recvar_is(ctx_t* c, const char* name) {
    for (int i = 0; i < c->n_recvar; i++) if (strcasecmp(c->recvar_name[i], name) == 0) return 1;
    return 0;
}

/* L'entry imap di un campo late-bound è PERMANENTE, ma i save/restore dell'imap usati dai
 * cicli FOR (push/pop di s->for_var, vedi più sotto) possono rimuoverla: la var globale resta
 * (dbf_field=1) e i read successivi emettevano il NOME NUDO (val nil, es. "ID: 0") invece
 * dell'espressione area-aware. Re-inserisce quindi l'entry se manca, a OGNI uso (idempotente). */
static void dbf_field_imap_ensure(ctx_t* c, const char* name) {
    char dx[256];
    if (!name || !*name) return;
    for (int i = 0; i < c->n_imap; i++)
        if (strcasecmp(c->imap_name[i], name) == 0) return;
    if (c->n_imap >= 32) return;
    snprintf(dx, sizeof(dx),
             "(gmb_db_current_dbf() > 0 ? gmb_db_dbf_field_val_name(gmb_db_current_dbf(), \"%s\") : gmb_rdd_get_field_str_name(\"%s\"))",
             name, name);
    c->imap_name[c->n_imap] = (char*)name;
    c->imap_expr[c->n_imap] = strdup(dx);
    c->n_imap++;
}

/* Late-binding Clipper (IMPORT DBF): un identificatore nudo NON dichiarato è un CAMPO
 * dell'area DBF corrente. Registra (una volta) una var boxed_val che, via imap, emette un
 * gmb_val_t TIPIZZATO a runtime (gmb_db_dbf_field_val_name). Ritorna il var_t, o NULL se
 * non è un caso di late-binding (var dichiarata, qualified, già gestito). */
static var_t* ensure_dbf_field_var(ctx_t* c, gmb_expr_t* e) {
    var_t* v;
    if (!c->dbf_clipper || !e || e->kind != GMB_EXPR_VAR || !e->var) return NULL;
    /* RECORD VAR da `DBF GET <var>`: `<var>.<campo>` è il CAMPO dell'area corrente (late
     * binding), NON un membro di struct. Prima diventava un globale `var_2Ecampo` a 0. */
    if (strchr(e->var, '.')) {
        const char* dot = strchr(e->var, '.');
        size_t pl = (size_t)(dot - e->var);
        if (pl > 0 && pl < 120) {
            char pre[128];
            memcpy(pre, e->var, pl); pre[pl] = 0;
            if (!strchr(dot + 1, '.') && dbf_recvar_is(c, pre)) {
                dbf_field_imap_ensure_as(c, e->var, dot + 1);
                v = lookup_var(c, e->var);
                if (!v) v = vars_add(&c->globals, e->var, TY_VAL);
                v->boxed_val = 1;
                v->dbf_field = 1;
                return v;
            }
        }
        return NULL;
    }
    if (e->ns_tk || e->var[0] == '_') return NULL;
    v = lookup_var(c, e->var);
    if (v) {
        if (!v->dbf_field) return NULL;
        dbf_field_imap_ensure(c, e->var);   /* ripristina se il save/restore FOR l'ha popata */
        return v;
    }
    /* AREA-AWARE: un campo nudo può appartenere a un'area DBF/ISAM (handle gmb_db) O a un'area
     * RDD (RDD USE … VIA "CSV"). Senza il fallback RDD, `Nome`/`Saldo` su un'area CSV davano 0
     * (bug RDD_ReplaceRealData.bas). Entrambe le funzioni ritornano gmb_val_t. */
    dbf_field_imap_ensure(c, e->var);
    v = vars_add(&c->globals, e->var, TY_VAL);
    v->boxed_val = 1;
    v->dbf_field = 1;
    /* TY_VAL, non suffix_type: un campo nudo è DINAMICO (il val è il TESTO del campo,
     * es. "100.00"). Con TY_NUM il PRINT/CSTR lo trattavano da numero (gmb_print_double /
     * gmb_str_basic) → "100" (divergenza dal canone PCode "100.00"). I contesti NUMERICI
     * (aritmetica/confronti) coerciscono via emit_num_operand → gmb_val_to_double(string). */
    return v;
}

/* True se e è una variabile NULLABLE (DIM x AS <tipo>?): in C è un gmb_val_t boxed, quindi
 * ogni uso NUMERICO va sballato con gmb_val_to_double (parità IL/VM-C). */
static int expr_is_nullable_var(ctx_t* c, gmb_expr_t* e) {
    if (!e || e->kind != GMB_EXPR_VAR || !e->var) return 0;
    var_t* v = lookup_var(c, e->var);
    return v && v->nullable;
}

/* True se e è `x.VALUE` con x nullable STRING (a runtime gmb_val_to_string). */
static int expr_value_is_str(ctx_t* c, gmb_expr_t* e) {
    if (!e || e->kind != GMB_EXPR_VAR || !e->var || e->tk != GMB_TOK_Value) return 0;
    const char* d = strchr(e->var, '.');
    if (!d || d == e->var) return 0;
    size_t l = (size_t)(d - e->var);
    char p[160];
    if (l >= sizeof(p)) return 0;
    memcpy(p, e->var, l); p[l] = 0;
    var_t* v = lookup_var(c, p);
    return v && v->nullable && v->type == TY_STR;
}

/* Emette un operando numerico sballando un eventuale nullable (gmb_val_t). */
void emit_expr(ctx_t* c, gmb_expr_t* e);
void emit_ident(ctx_t* c, const char* name);
static int is_json_path_member(ctx_t* c, gmb_expr_t* e, var_t** out_bv, const char** out_m);
int is_json_index_member_call(ctx_t* c, gmb_expr_t* e);
static void emit_num_from_json_member(ctx_t* c, gmb_expr_t* e);

/* Member di una var REGEX (`r.Pattern`, get) o di una lista boxed (`x.Count`/`x.Length`).
 * Ritorna 1 e imposta *out_v (var base) + *out_kind (1 = regex.Pattern, 2 = lista.Count). */
static int regex_list_member(ctx_t* c, const char* var, var_t** out_v, int* out_kind) {
    if (!var) return 0;
    const char* dot = strchr(var, '.');
    if (!dot || dot == var || strchr(dot + 1, '.')) return 0;
    char pre[160]; size_t pl = (size_t)(dot - var);
    if (pl >= sizeof(pre)) return 0;
    memcpy(pre, var, pl); pre[pl] = 0;
    var_t* bv = lookup_var(c, pre);
    if (!bv) return 0;
    const char* m = dot + 1;
    if (bv->regex_obj && !strcasecmp(m, "Pattern")) { if (out_v) *out_v = bv; if (out_kind) *out_kind = 1; return 1; }
    if (bv->boxed_val && !bv->vclass[0] && (!strcasecmp(m, "Count") || !strcasecmp(m, "Length"))) {
        if (out_v) *out_v = bv; if (out_kind) *out_kind = 2; return 1;
    }
    return 0;
}

int etype(ctx_t* c, gmb_expr_t* e);   /* forward: usata qui sotto + emit_str_operand */
static int comp_src_is_str(ctx_t* c, gmb_expr_t* src);   /* forward: sorgente FOR di una comprehension produce stringhe */
void emit_num_operand(ctx_t* c, gmb_expr_t* e) {
    /* TY_VAL (getter RDD/dinamico): in contesto NUMERICO → gmb_val_to_double. */
    if (e && etype(c, e) == TY_VAL) {
        sb_put(&c->out, "gmb_val_to_double(");
        emit_expr(c, e);
        sb_put(&c->out, ")");
        return;
    }
    /* Membro di val boxata SENZA schema (`sec.Timeout`) in contesto NUMERICO: accesso
     * numerico. Prima emetteva la forma testuale (gmb_json_path_text, una STRINGA) e il
     * confronto con un numero non compilava (`wsec.Timeout = 1234`). */
    {
        var_t* jpv = NULL; const char* jpm = NULL;
        if (is_json_path_member(c, e, &jpv, &jpm)) {
            sb_put(&c->out, "gmb_val_to_double(gmb_dict_get(gmb_val_as_dict(");
            emit_ident(c, jpv->name);
            sb_put(&c->out, "), \"");
            for (const char* p = jpm; *p; p++) {
                if (*p == '"' || *p == '\\') sb_put(&c->out, "\\");
                sb_putn(&c->out, p, 1);
            }
            sb_put(&c->out, "\"))");
            return;
        }
    }
    if (expr_is_nullable_var(c, e)) {
        var_t* v = lookup_var(c, e->var);
        if (v && v->type != TY_STR) {
            sb_put(&c->out, "gmb_val_to_double(");
            emit_expr(c, e);
            sb_put(&c->out, ")");
            return;
        }
    }
    /* var boxed_val (gmb_val_t) in contesto NUMERICO: unbox con gmb_val_to_double. Prima
     * `vs = vs + v` con v boxed (da `FOR EACH k, v IN <json>`) non compilava
     * (gmb_double_t + gmb_val_t). */
    /* STRINGA numerica in contesto numerico (es. ABS("-3.5")): coercizione esplicita. */
    if (e && etype(c, e) == TY_STR) {
        sb_put(&c->out, "gmb_string_to_double(");
        emit_expr(c, e);
        sb_put(&c->out, ")");
        return;
    }
    if (e && e->kind == GMB_EXPR_VAR && e->var && !strchr(e->var, '.')) {
        var_t* nbv = lookup_var(c, e->var);
        if (nbv && nbv->boxed_val && !nbv->gkind && !nbv->vclass[0] && !nbv->stats_val && !nbv->boxed_md) {
            sb_put(&c->out, "gmb_val_to_double(");
            emit_expr(c, e);
            sb_put(&c->out, ")");
            return;
        }
    }
    emit_expr(c, e);
}

/* Keyword C (C11 + estensioni comuni) con cui un identificatore BASIC emesso tal quale può
 * collidere — bug Identificatore-BASIC-Come-Keyword-C (AiWiki, trovato 2026-09-16): un nome
 * come "auto" (perfettamente lecito in BASIC: `DIM auto AS STRING`) produceva C non
 * compilabile perché "auto" è una storage-class C, con un errore del compilatore C
 * fuorviante e lontano dalla vera causa ("expected expression" sull'USO, non sulla
 * dichiarazione — il caret non punta mai al nome incriminato). Confronto case-sensitive,
 * come le keyword C stesse: un identificatore BASIC che differisce solo per maiuscole/
 * minuscole (`Auto`, `AUTO`) non collide davvero in C. */
static int sb_ident_is_c_keyword(const char* name) {
    static const char* const kws[] = {
        "auto", "break", "case", "char", "const", "continue", "default", "do",
        "double", "else", "enum", "extern", "float", "for", "goto", "if",
        "inline", "int", "long", "register", "restrict", "return", "short",
        "signed", "sizeof", "static", "struct", "switch", "typedef", "union",
        "unsigned", "void", "volatile", "while",
        "_Alignas", "_Alignof", "_Atomic", "_Bool", "_Complex", "_Generic",
        "_Imaginary", "_Noreturn", "_Static_assert", "_Thread_local",
        /* Non-keyword ma identificatori della LIBC che collidono con nomi BASIC: il C emesso
         * include <stdio.h>/<stdlib.h>/<stdint.h>, quindi una variabile `FILE` (es.
         * ClipperDbfLateBinding.bas) finiva in `static gmb_val_t FILE` → "redefinition of
         * 'FILE' as different kind of symbol". Stesso trattamento delle keyword: prefisso. */
        "FILE", "NULL", "EOF", "stdin", "stdout", "stderr",
        "size_t", "ssize_t", "ptrdiff_t", "off_t", "time_t", "pid_t", "errno",
        "bool", "true", "false", "main",
        NULL
    };
    for (int i = 0; kws[i]; i++) if (strcmp(name, kws[i]) == 0) return 1;
    return 0;
}
/* Identificatore C-safe: '$'/'%' e altri caratteri fuori [A-Za-z0-9_] codificati, una
 * keyword C esatta (sb_ident_is_c_keyword sopra) riceve un prefisso deterministico. UNICO
 * punto di emissione di un identificatore C-safe in tutto l'emitter (usata direttamente o
 * via emit_ident/sb_ident_to, 500+ call site) — dichiarazioni, usi, parametri e campi UDT
 * dello STESSO nome BASIC concordano automaticamente sullo stesso nome C alterato perché
 * passano tutti da qui, senza bisogno di una mappa separata. */
static void sb_ident(sb_t* b, const char* name) {
    char nb[256]; name = norm_var(name, nb, sizeof nb);   /* `X#`→`X` (suffisso tipo non è il nome) */
    if (sb_ident_is_c_keyword(name)) sb_put(b, "gmb_kw_");
    for (const char* p = name; *p; p++) {
        if (isalnum((unsigned char)*p) || *p == '_') sb_putn(b, p, 1);
        else if (*p == '$') sb_put(b, "_S");
        else if (*p == '%') sb_put(b, "_I");
        else sb_printf(b, "_%02X", (unsigned char)*p);
    }
}
/* Come sb_ident ma su buffer esterno: ritorna il puntatore di fine (per comporre
 * nomi C di struct/variabili closure, FASE 2.6(j)). */
static char* sb_ident_to(char* dst, const char* name) {
    sb_t b; memset(&b, 0, sizeof(b)); b.s = dst; b.len = 0; b.cap = SIZE_MAX;
    sb_ident(&b, name);
    dst[b.len] = 0;
    return dst + b.len;
}
void emit_ident(ctx_t* c, const char* name) {
    for (int i = 0; i < c->n_imap; i++)
        if (strcasecmp(c->imap_name[i], name) == 0) { sb_put(&c->out, c->imap_expr[i]); return; }
    sb_ident(&c->out, name);
}
static const char* ctype_name(int ty) { return ty == TY_STR ? "gmb_string_t" : (ty == TY_VAL ? "gmb_val_t" : "gmb_double_t"); }

/* esposta a gmb_c99_emit_builtin.c (TU separata, enum GK locale qui): se `name` è una
 * variabile-collezione emette JSON.Stringify(v) via gmb_val_to_json del val boxato (1),
 * altrimenti 0 (l'array nativo resta gestito dal chiamante). */
int gmb_c99_emit_coll_json(ctx_t* c, const char* name) {
    var_t* av = lookup_var(c, name);
    if (!av || !av->gkind) return 0;
    if (gk_is_dict(av->gkind)) {
        sb_put(&c->out, "gmb_val_to_json(gmb_make_val_dict(");
        sb_ident(&c->out, av->name);
        sb_put(&c->out, "))");
        return 1;
    }
    if (gk_is_list(av->gkind)) {
        sb_put(&c->out, "gmb_val_to_json(gmb_make_val_list(");
        sb_ident(&c->out, av->name);
        sb_put(&c->out, "))");
        return 1;
    }
    return 0;
}
/* per gmb_c99_emit_builtin.c: 0 = non-collezione, 1 = list-family, 2 = dict-family */
int gmb_c99_var_coll_kind(ctx_t* c, const char* name) {
    var_t* av = lookup_var(c, name);
    if (!av || !av->gkind) return 0;
    if (gk_is_list(av->gkind)) return 1;
    if (gk_is_dict(av->gkind)) return 2;
    return 0;
}
int gmb_c99_var_coll_sorted(ctx_t* c, const char* name) {
    var_t* av = lookup_var(c, name);
    return av && av->gkind == GK_SORTED;
}

/* Variabile bound della dimensione k di un array: <ident>__b<k> (tracciata al DIM). */
static void sb_bound_ident(sb_t* b, const char* arr, int k) {
    sb_ident(b, arr);
    sb_printf(b, "__b%d", k);
}

/* 2.8: parametro array BYREF (REDIM nel body, parity _byRefArrayParams oracolo):
 * nel corpo la funzione usa l'alias locale "_<ident>" (inizializzato da *<ident>
 * nel prologo e riscritto al chiamante prima di ogni return). */
void emit_var_ref(ctx_t* c, const var_t* v) {
    if (v->arr_byref) sb_put(&c->out, "_");
    emit_ident(c, v->name);
}
void sb_bound_var(sb_t* b, const var_t* v, int k) {
    if (v->arr_byref) sb_put(b, "_");
    sb_bound_ident(b, v->name, k);
}
/* Lower bound compagna `<ident>__blo` (canone 1-based 2026-09-30): assegnata al DIM con
 * TO, letta da FOR EACH (inizio) e LBOUND. Esiste solo se il DIM l'ha emessa (flag). */
static void sb_bound_lo(sb_t* b, const var_t* v) {
    if (v->arr_byref) sb_put(b, "_");
    sb_ident(b, v->name);
    sb_put(b, "__blo");
}

/* ─────────────── FASE 2.6(b): helper GPM (parità oracolo C# Gpm.cs) ─────────────── */

static const char* gkind_ctype(int gk) {
    switch (gk) {
    case GK_CHAN: return "gmb_chan_t*";
    case GK_WG: return "gmb_wg_t*";
    case GK_MUTEX: return "gmb_gmutex_t*";
    case GK_RWMUTEX: return "gmb_grwmutex_t*";
    case GK_ONCE: return "gmb_gonce_t*";
    case GK_COND: return "gmb_gcond_t*";
    case GK_ATOMIC: return "gmb_atomic_t*";
    case GK_POOL: return "gmb_pool_t*";
    case GK_SYNCMAP: return "gmb_syncmap_t*";
    case GK_CONTEXT: return "gmb_gcontext_t*";
    case GK_HTTPREQ: return "gmb_val_t";
    case GK_HTTPRESP: return "gmb_val_t";
    case GK_WEBSOCKET: return "gmb_val_t";
    case GK_GRAPH: return "int64_t";
    case GK_MATRIX: return "int64_t";
    case GK_FUNCVAL: return "gmb_fn_t";
    default: return NULL;
    }
}
/* Nome-tipo UDT di una variabile (mappa popolata al DIM, dove cls_find risolve il tipo).
 * Ritorna 1 e scrive il nome in out se la var è un UDT noto. Usata da JSON.TOJSON(udt):
 * la var risolta in un altro scope può avere vclass vuota (doppia registrazione). */
int gmb_udt_var_type(ctx_t* c, const char* name, char* out, int cap) {
    if (!c || !name || !out || cap <= 0) return 0;
    for (int i = 0; i < c->n_udt_var_names; i++)
        if (strcmp(c->udt_var_names[i][0], name) == 0) { snprintf(out, (size_t)cap, "%s", c->udt_var_names[i][1]); return 1; }
    return 0;
}
/* Testo del tipo dichiarato di una variabile DIM ("INTEGER", "STRING * 10", "MyUDT", ...).
 * Solo questo TU legge la mappa (vedi ctx_t::var_type_text); ritorna 0 se la variabile non è
 * stata dichiarata con un tipo esplicito (DIM x = … → tipo inferito).
 * Il SUFFISSO BASIC ($ % ! #) è grafia, non identità: la mappa è chiave-normalizzata e anche
 * la query lo è, così SIZEOF(sv) risolve il tipo di una `DIM sv$` (parità con le gambe
 * gestite, che leggono il simbolo del linker dove il suffisso dichiara il tipo statico). */
static const char* gmb_name_no_suffix(const char* name, char* buf, int cap) {
    if (!name || !buf || cap <= 0) return "";
    size_t n = strlen(name);
    if (n > 1) {
        char sx = name[n - 1];
        if (sx == '$' || sx == '%' || sx == '!' || sx == '#') {
            snprintf(buf, (size_t)cap, "%.*s", (int)(n - 1), name);
            return buf;
        }
    }
    snprintf(buf, (size_t)cap, "%s", name);
    return buf;
}
/* Tipo statico dichiarato dal SOLO suffisso (DIM v$ senza AS): STRING dinamica (→ -1 nel
 * canone), INTEGER, SINGLE, DOUBLE. */
static const char* gmb_suffix_type(char sx) {
    switch (sx) {
        case '$': return "STRING";
        case '%': return "INTEGER";
        case '!': return "SINGLE";
        case '#': return "DOUBLE";
        default: return NULL;
    }
}
int gmb_var_declared_type(ctx_t* c, const char* name, char* out, int cap) {
    if (!c || !name || !out || cap <= 0) return 0;
    char key[40];
    const char* k = gmb_name_no_suffix(name, key, sizeof key);
    for (int i = 0; i < c->n_var_type_text; i++)
        if (strcasecmp(c->var_type_text[i][0], k) == 0) { snprintf(out, (size_t)cap, "%s", c->var_type_text[i][1]); return 1; }
    return 0;
}
/* Vero se l'espressione e' un valore DATA/ORA (canone: NOW()/TODAY() -> kind DATETIME nel
 * value-model C, cosi' JSON ISO-8601 e PRINT leggibile differiscono dal numero). */
int gmb_expr_is_datetime(ctx_t* c, gmb_expr_t* e) {
    if (!e) return 0;
    if (e->tk == GMB_TOK_Now || e->tk == GMB_TOK_Today) return 1;
    if (e->kind == GMB_EXPR_VAR && e->var) {
        char ty[32];
        if (gmb_var_declared_type(c, e->var, ty, sizeof ty) && strcasecmp(ty, "DATETIME") == 0) return 1;
    }
    return 0;
}
static void sb_var_ctype(sb_t* b, var_t* v) {
    if (v->sb_builder) { sb_put(b, "gmb_stringbuilder_t*"); return; }
    /* Contenitore tipizzato a handle (HEAP/MAXHEAP/BAG/TRIE): è un gmb_val_t boxed, NON una
     * gmb_list_t — la stessa rappresentazione che usa il runtime condiviso. */
    if (v->coll_handle) { sb_put(b, "gmb_val_t"); return; }
    if (v->nullable) { sb_put(b, "gmb_val_t"); return; }
    if (v->type == TY_VAL || (v->boxed_val && !v->gkind && !v->vclass[0])) { sb_put(b, "gmb_val_t"); return; }
    if (v->vclass[0]) {
        /* 2.7: istanza di classe boxed. BYREF → gmb_val_t* (puntatore all'istanza boxed). */
        if (v->byref) { sb_put(b, "gmb_val_t*"); return; }
        sb_put(b, "gmb_val_t"); return;
    }
    const char* gk = v->gkind ? gkind_ctype(v->gkind) : NULL;
    if (v->gkind == GK_GEN) { sb_put(b, "gmb_gen_"); sb_ident(b, v->gen_id); sb_put(b, "_t"); return; }
    if (gk_is_list(v->gkind)) { sb_put(b, "gmb_list_t"); return; }
    if (gk_is_dict(v->gkind)) { sb_put(b, "gmb_dict_t"); return; }
    if (gk) { sb_put(b, gk); return; }
    if (v->jagged) { sb_put(b, "gmb_double_t**"); return; }
    sb_put(b, ctype_name(v->type));
    if (v->byref) sb_put(b, "*");
    else if (v->is_array && !v->matrix && !v->dyn_len && !v->arr_byref) sb_put(b, "*");
}

/* PARAMARRAY (2026-08-31, audit §6): il parametro variadico finale si comporta come un
 * parametro ARRAY (puntatore + bound compagno) per ogni scopo di emissione — stesso
 * trattamento di param_is_array, così l'intera macchina esistente per gli array-parametro
 * (lettura nel body, firma, prototipo) si applica senza duplicazione. */
static int p_arraylike(const gmb_stmt_t* s, int i) {
    if (!s || i < 0 || i >= s->n_params) return 0;
    if (s->param_is_array && s->param_is_array[i]) return 1;
    if (s->param_variadic && s->param_variadic[i]) return 1;
    return 0;
}
static int sync_gkind_tok(int tk) {
    switch (tk) {
        case GMB_TOK_Channel: return GK_CHAN;
        case GMB_TOK_Waitgroup: return GK_WG;
        case GMB_TOK_Mutex: return GK_MUTEX;
        case GMB_TOK_RwMutex: return GK_RWMUTEX;
        case GMB_TOK_Once: return GK_ONCE;
        case GMB_TOK_Cond: return GK_COND;
        case GMB_TOK_Atomic: return GK_ATOMIC;
        case GMB_TOK_Pool: return GK_POOL;
        case GMB_TOK_SyncMap:
        case GMB_TOK_ConcurrentMap: return GK_SYNCMAP;
        case GMB_TOK_Context: return GK_CONTEXT;
        case GMB_TOK_HttpRequest: return GK_HTTPREQ;
        case GMB_TOK_HttpResponse: return GK_HTTPRESP;
        case GMB_TOK_WebSocket: return GK_WEBSOCKET;
        case GMB_TOK_Function: return GK_FUNCVAL;
        default: return GK_PLAIN;
    }
}

/* lista DEFER dello scope corrente (fn o top-level) */
static void defer_add(ctx_t* c, gmb_stmt_t* body) {
    gmb_stmt_t*** arr; int* n; int* cap;
    if (c->cur_fn) { arr = &c->cur_fn->defers; n = &c->cur_fn->n_defers; cap = &c->cur_fn->defer_cap; }
    else { arr = &c->top_defers; n = &c->n_top_defers; cap = &c->top_defer_cap; }
    if (*n >= *cap) { *cap = *cap ? *cap * 2 : 4; *arr = (gmb_stmt_t**)realloc(*arr, (size_t)(*cap) * sizeof(gmb_stmt_t*)); }
    (*arr)[(*n)++] = body;
}
int defer_count(ctx_t* c) { return c->cur_fn ? c->cur_fn->n_defers : c->n_top_defers; }
const char* defer_exit_label(ctx_t* c) { return c->cur_fn ? "__dfx_exit" : "__dfxt_exit"; }

/* DONE esplicito nel body (per il Done implicito del wrapper GO, parity oracolo) */
static int body_has_done(gmb_stmt_t** list, int n) {
    for (int i = 0; i < n; i++) {
        gmb_stmt_t* s = list[i];
        if (!s) continue;
        if (s->kind == GMB_STMT_DONE) return 1;
        if (body_has_done(s->then_body, s->n_then)) return 1;
        if (body_has_done(s->else_body, s->n_else)) return 1;
        if (body_has_done(s->for_body, s->n_for)) return 1;
        if (body_has_done(s->while_body, s->n_while)) return 1;
        if (body_has_done(s->do_body, s->n_do)) return 1;
        if (body_has_done(s->func_body, s->n_funcbody)) return 1;
        for (int k = 0; k < s->n_select_cases; k++)
            if (s->select_cases[k] && body_has_done(s->select_cases[k]->case_body, s->select_cases[k]->n_case_body)) return 1;
        if (s->kind == GMB_STMT_GOSELECT)
            for (int k = 0; k < s->n_go_cases; k++)
                if (body_has_done(s->go_cases[k].body, s->go_cases[k].n_body)) return 1;
    }
    return 0;
}

/* 2.6(s): GOSUB presente nel body (ricorsivo, escludendo funzioni nidificate)? */
static int body_has_gosub(gmb_stmt_t** list, int n) {
    for (int i = 0; i < n; i++) {
        gmb_stmt_t* s = list[i];
        if (!s) continue;
        if (s->kind == GMB_STMT_FUNCTION) continue;
        if (s->kind == GMB_STMT_GOSUB) return 1;
        if (body_has_gosub(s->then_body, s->n_then)) return 1;
        if (body_has_gosub(s->else_body, s->n_else)) return 1;
        if (body_has_gosub(s->for_body, s->n_for)) return 1;
        if (body_has_gosub(s->while_body, s->n_while)) return 1;
        if (body_has_gosub(s->do_body, s->n_do)) return 1;
        if (body_has_gosub(s->try_body, s->n_try)) return 1;
        for (int k = 0; k < s->n_catch; k++)
            if (s->catch_body[k] && body_has_gosub(s->catch_body[k]->catch_body, s->catch_body[k]->n_catch)) return 1;
        if (body_has_gosub(s->finally_body, s->n_finally)) return 1;
        for (int k = 0; k < s->n_select_cases; k++)
            if (s->select_cases[k] && body_has_gosub(s->select_cases[k]->case_body, s->select_cases[k]->n_case_body)) return 1;
        if (s->kind == GMB_STMT_GOSELECT)
            for (int k = 0; k < s->n_go_cases; k++)
                if (body_has_gosub(s->go_cases[k].body, s->go_cases[k].n_body)) return 1;
    }
    return 0;
}

/* indentazione: non-static perché dichiarata in gmb_c99_emit_internal.h — i file di
 * dominio esterni (gmb_c99_emit_team.c, gmb_c99_emit_ai_sb.c) la usano */
void ind(ctx_t* c) { for (int i = 0; i < c->indent; i++) sb_put(&c->out, "    "); }
/* Marca l'uso di un widget TUI (setter esposto ai file di dominio): il layout di
 * ctx_t vive QUI, non nell'header (duplicato storico) - settare il campo da un
 * file di dominio scriverebbe a un offset potenzialmente diverso. */
void c99_mark_tui(ctx_t* c) { c->uses_tui = 1; c->uses_ui = 1; }
void c99_mark_ui(ctx_t* c) { c->uses_ui = 1; }

/* 2.6(s): lo scope corrente (funzione o top level) contiene siti GOSUB? */
static int cur_scope_has_gosub(ctx_t* c) {
    return c->cur_fn ? c->cur_fn->has_gosub : c->top_has_gosub;
}

/* 2.6(s): RETURN di scope con siti GOSUB — pop dello stack condiviso e salto al
 * backlabel del sito attivo (parity oracolo _gosubSites/__gb_gosub_stack); <alt>
 * è l'uscita normale quando lo stack è vuoto. L'indent iniziale è già emesso. */
static void emit_gosub_return(ctx_t* c, const char* alt) {
    if (c->n_gosub_sites == 0) { sb_put(&c->out, alt); sb_put(&c->out, "\n"); return; }
    sb_put(&c->out, "if (__gb_gosub_sp > 0) {\n");
    c->indent++;
    ind(c); sb_put(&c->out, "switch (__gb_gosub_stack[--__gb_gosub_sp]) {\n");
    c->indent++;
    for (int i = 0; i < c->n_gosub_sites; i++) {
        ind(c); sb_printf(&c->out, "case %d: goto %s;\n", c->gosub_sites[i].id, c->gosub_sites[i].back);
    }
    ind(c); sb_printf(&c->out, "default: goto %s;\n", c->gosub_sites[0].back);
    c->indent--;
    ind(c); sb_put(&c->out, "}\n");
    c->indent--;
    ind(c); sb_printf(&c->out, "} else { %s }\n", alt);
}

/* label <name> presente nel body (ricorsivo)? — scope check ON ERROR GOTO/RESUME */
static int label_in_body(gmb_stmt_t** list, int n, const char* name) {
    for (int i = 0; i < n; i++) {
        gmb_stmt_t* s = list[i];
        if (!s) continue;
        if (s->kind == GMB_STMT_LABEL && s->target_label && strcasecmp(s->target_label, name) == 0) return 1;
        if (label_in_body(s->then_body, s->n_then, name)) return 1;
        if (label_in_body(s->else_body, s->n_else, name)) return 1;
        if (label_in_body(s->for_body, s->n_for, name)) return 1;
        if (label_in_body(s->while_body, s->n_while, name)) return 1;
        if (label_in_body(s->do_body, s->n_do, name)) return 1;
        for (int k = 0; k < s->n_select_cases; k++)
            if (s->select_cases[k] && label_in_body(s->select_cases[k]->case_body, s->select_cases[k]->n_case_body, name)) return 1;
    }
    return 0;
}

/* Il body (esclusi i corpi di funzioni nidificate) contiene una riga numerata tv? */
static void body_collect_gosub_nums(gmb_stmt_t** list, int n, int* out, int* no) {
    for (int i = 0; i < n && *no < 64; i++) {
        gmb_stmt_t* s = list[i];
        if (!s) continue;
        if (s->kind == GMB_STMT_FUNCTION) continue;
        if (s->kind == GMB_STMT_GOSUB && s->target_label) {
            int alln = 1;
            for (const char* q = s->target_label; *q; q++) if (*q < '0' || *q > '9') { alln = 0; break; }
            if (alln) out[(*no)++] = atoi(s->target_label);
        }
        body_collect_gosub_nums(s->then_body, s->n_then, out, no);
        body_collect_gosub_nums(s->else_body, s->n_else, out, no);
        body_collect_gosub_nums(s->for_body, s->n_for, out, no);
        body_collect_gosub_nums(s->while_body, s->n_while, out, no);
        body_collect_gosub_nums(s->do_body, s->n_do, out, no);
        for (int k = 0; k < s->n_select_cases; k++)
            if (s->select_cases[k]) body_collect_gosub_nums(s->select_cases[k]->case_body, s->select_cases[k]->n_case_body, out, no);
    }
}
static int fn_body_has_line(gmb_stmt_t** list, int n, int tv) {
    for (int i = 0; i < n; i++) {
        gmb_stmt_t* s = list[i];
        if (!s) continue;
        if (s->kind == GMB_STMT_FUNCTION) continue;
        if (s->bas_line == tv) return 1;
        if (fn_body_has_line(s->then_body, s->n_then, tv)) return 1;
        if (fn_body_has_line(s->else_body, s->n_else, tv)) return 1;
        if (fn_body_has_line(s->for_body, s->n_for, tv)) return 1;
        if (fn_body_has_line(s->while_body, s->n_while, tv)) return 1;
        if (fn_body_has_line(s->do_body, s->n_do, tv)) return 1;
        for (int k = 0; k < s->n_select_cases; k++)
            if (s->select_cases[k] && fn_body_has_line(s->select_cases[k]->case_body, s->select_cases[k]->n_case_body, tv)) return 1;
    }
    return 0;
}

/* 2.8: raccoglie i target numerici (righe di programma) di GOTO/GOSUB in ogni
 * blocco, così il loop top-level può emettere le label lbl_<N> corrispondenti. */
static void collect_num_targets(gmb_stmt_t** list, int n, int* out, int* no) {
    for (int i = 0; i < n; i++) {
        gmb_stmt_t* s = list[i];
        if (!s) continue;
        if ((s->kind == GMB_STMT_GOTO || s->kind == GMB_STMT_GOSUB
             || (s->kind == GMB_STMT_ON_ERROR && s->target_label)) && s->target_label && s->target_label[0]) {
            int allnum = 1;
            for (const char* q = s->target_label; *q; q++) if (*q < '0' || *q > '9') { allnum = 0; break; }
            if (allnum) {
                int v = atoi(s->target_label), dup = 0;
                for (int k = 0; k < *no; k++) if (out[k] == v) { dup = 1; break; }
                if (!dup && *no < 64) out[(*no)++] = v;
            }
        }
        collect_num_targets(s->then_body, s->n_then, out, no);
        collect_num_targets(s->else_body, s->n_else, out, no);
        collect_num_targets(s->for_body, s->n_for, out, no);
        collect_num_targets(s->while_body, s->n_while, out, no);
        collect_num_targets(s->do_body, s->n_do, out, no);
        collect_num_targets(s->func_body, s->n_funcbody, out, no);
        collect_num_targets(s->try_body, s->n_try, out, no);
        collect_num_targets(s->catch_body, s->n_catch, out, no);
        collect_num_targets(s->finally_body, s->n_finally, out, no);
        for (int k = 0; k < s->n_select_cases; k++)
            if (s->select_cases[k]) collect_num_targets(s->select_cases[k]->case_body, s->select_cases[k]->n_case_body, out, no);
    }
}

/* 2.8: DATA/READ/RESTORE — raccoglie i valori DATA (ordine di programma) e le
 * label (per risolvere RESTORE <label> alla posizione del primo DATA dopo). */
static void collect_data_items(ctx_t* c, gmb_stmt_t** list, int n) {
    for (int i = 0; i < n && !c->error[0]; i++) {
        gmb_stmt_t* s = list[i];
        if (!s) continue;
        if (s->kind == GMB_STMT_DATA) {
            for (int k = 0; k < s->n_data && !c->error[0]; k++) {
                gmb_expr_t* e = s->data_values[k];
                if (c->n_data_items >= c->data_cap) {
                    c->data_cap = c->data_cap ? c->data_cap * 2 : 16;
                    c->data_items = (struct data_item*)realloc(c->data_items, (size_t)c->data_cap * sizeof(*c->data_items));
                }
                struct data_item* it = &c->data_items[c->n_data_items++];
                it->is_str = 0; it->sval = NULL; it->dval = 0;
                it->bas_line = s->bas_line > 0 ? s->bas_line : s->line;
                if (e && e->kind == GMB_EXPR_NUM) it->dval = e->num;
                else if (e && e->kind == GMB_EXPR_STR) { it->is_str = 1; it->sval = strdup(e->str ? e->str : ""); }
                else if (e && e->kind == GMB_EXPR_VAR) { it->is_str = 1; it->sval = strdup(e->var ? e->var : ""); }
                else if (e && e->kind == GMB_EXPR_UNARY && e->op && strcmp(e->op, "-") == 0
                         && e->left && e->left->kind == GMB_EXPR_NUM) it->dval = -e->left->num;
                else { c99_fail(c, s->line, "DATA: valore non letterale non supportato dall'emitter nativo"); return; }
            }
        } else if (s->kind == GMB_STMT_LABEL && s->target_label && c->n_data_labels < 64) {
            snprintf(c->data_labels[c->n_data_labels].name, 64, "%s", s->target_label);
            c->data_labels[c->n_data_labels].line = s->bas_line > 0 ? s->bas_line : s->line;
            c->n_data_labels++;
        }
        collect_data_items(c, s->then_body, s->n_then);
        collect_data_items(c, s->else_body, s->n_else);
        collect_data_items(c, s->for_body, s->n_for);
        collect_data_items(c, s->while_body, s->n_while);
        collect_data_items(c, s->do_body, s->n_do);
        collect_data_items(c, s->func_body, s->n_funcbody);
        collect_data_items(c, s->try_body, s->n_try);
        collect_data_items(c, s->catch_body, s->n_catch);
        collect_data_items(c, s->finally_body, s->n_finally);
        for (int k = 0; k < s->n_select_cases; k++)
            if (s->select_cases[k]) collect_data_items(c, s->select_cases[k]->case_body, s->select_cases[k]->n_case_body);
    }
}

/* pre-pass: il programma usa GPM? (GO/SEND/RECEIVE/... in qualunque blocco)
 * Rileva anche ON ERROR/RESUME (FASE 2.6c) per i guard setjmp sui LET. */
static int gpm_kind_p(int k) {
    return k == GMB_STMT_GO || k == GMB_STMT_GOEXIT || k == GMB_STMT_GOSELECT ||
           k == GMB_STMT_SEND || k == GMB_STMT_RECEIVE || k == GMB_STMT_CHANNEL ||
           k == GMB_STMT_MUTEX || k == GMB_STMT_COND || k == GMB_STMT_WAIT ||
           k == GMB_STMT_DONE || k == GMB_STMT_ONCE || k == GMB_STMT_DEFER ||
           k == GMB_STMT_TIMEOUT || k == GMB_STMT_IOWATCH;
}
static int onerr_stmt_p(gmb_stmt_t* s) {
    return s->kind == GMB_STMT_ON_ERROR && s->on_kind && strncmp(s->on_kind, "ERROR", 5) == 0;
}
/* Modo GPM richiesto dal chiamante: 0 auto (rilevamento), 1 always (forza scheduler),
 * 2 linear (usa il percorso diretto quando il programma è genuinamente lineare: stesso
 * rilevamento di auto, mai crash). */
static int g_gpm_mode = 0;
void gmb_c99_set_gpm_mode(int mode) { g_gpm_mode = mode; }

static void gpm_scan(ctx_t* c, gmb_stmt_t* s) {
    if (!s || (c->uses_gpm && c->uses_onerror)) return;
    if (g_gpm_mode == 1) c->uses_gpm = 1;   /* --gpm always: rete di sicurezza */
    if (gpm_kind_p((int)s->kind)) c->uses_gpm = 1;
    /* HTTP ROUTE (net_sub 15) / HTTP USE (net_sub 18): il wrapper esegue l'handler come
     * task GPM (stessa condizione di st_net_cmd) → va deciso PRIMA di emettere l'entry,
     * altrimenti senza SUB Main l'entry esce `gmb_program_main` ma main() chiama
     * `gmb_module_entry` (HttpServerCookies: entry non definito → cc fallisce). */
    if (s->kind == GMB_STMT_NET_CMD && (s->net_sub == 15 || s->net_sub == 18)) c->uses_gpm = 1;
    if (onerr_stmt_p(s)) c->uses_onerror = 1;
    if (c->uses_gpm && c->uses_onerror) return;
    for (int i = 0; i < s->n_then; i++) gpm_scan(c, s->then_body[i]);
    for (int i = 0; i < s->n_else; i++) gpm_scan(c, s->else_body[i]);
    for (int i = 0; i < s->n_for; i++) gpm_scan(c, s->for_body[i]);
    for (int i = 0; i < s->n_while; i++) gpm_scan(c, s->while_body[i]);
    for (int i = 0; i < s->n_do; i++) gpm_scan(c, s->do_body[i]);
    for (int i = 0; i < s->n_funcbody; i++) gpm_scan(c, s->func_body[i]);
    for (int i = 0; i < s->n_select_cases; i++)
        if (s->select_cases[i])
            for (int k = 0; k < s->select_cases[i]->n_case_body; k++)
                gpm_scan(c, s->select_cases[i]->case_body[k]);
}

/* 2.8: pre-scan REDIM di <name> nel body (parity oracolo C99CodeEmitter.cs:614-647:
 * il parametro array REDIMmato va passato con doppia indirection). */
static int stmt_redim_name(gmb_stmt_t* s, const char* name) {
    if (!s) return 0;
    if (s->kind == GMB_STMT_REDIM && s->dim_var && strcasecmp(s->dim_var, name) == 0) return 1;
    for (int i = 0; i < s->n_then; i++) if (stmt_redim_name(s->then_body[i], name)) return 1;
    for (int i = 0; i < s->n_else; i++) if (stmt_redim_name(s->else_body[i], name)) return 1;
    for (int i = 0; i < s->n_for; i++) if (stmt_redim_name(s->for_body[i], name)) return 1;
    for (int i = 0; i < s->n_while; i++) if (stmt_redim_name(s->while_body[i], name)) return 1;
    for (int i = 0; i < s->n_do; i++) if (stmt_redim_name(s->do_body[i], name)) return 1;
    for (int i = 0; i < s->n_select_cases; i++)
        if (s->select_cases[i])
            for (int k = 0; k < s->select_cases[i]->n_case_body; k++)
                if (stmt_redim_name(s->select_cases[i]->case_body[k], name)) return 1;
    return 0;
}

/* epilogo DEFER: label + body LIFO + return (parity __defer_exit dell'oracolo) */
static gmb_expr_t* dbf_scope_arg(gmb_expr_t** a, int na);
static int dbf_cond_text(ctx_t* c, gmb_expr_t* e, char* out, int cap);
static int dbf_cond_text_q(ctx_t* c, gmb_expr_t* e, char* out, int cap, int keep_qual);
static int dbf_cond_text_keepq(ctx_t* c, gmb_expr_t* e, char* out, int cap);
static void emit_dbf_scope_single(ctx_t* c, gmb_expr_t** a, int na, int is_recall);
static void emit_stmt(ctx_t* c, gmb_stmt_t* s);
static void emit_src_line(ctx_t* c, int line);   /* O8: `#line` verso il `.bas` */
static void emit_arr_wb(ctx_t* c);
static void emit_class_locals_dtors(ctx_t* c);   /* forward: usata da emit_defer_epilogue */
struct cls_info* cls_find(ctx_t* c, const char* name);   /* forward: usata da emit_class_locals_dtors. Non-static: condivisa con gmb_c99_emit_speed.c. */
static void emit_defer_epilogue(ctx_t* c) {
    gmb_stmt_t** arr; int n;
    if (c->cur_fn) { arr = c->cur_fn->defers; n = c->cur_fn->n_defers; }
    else { arr = c->top_defers; n = c->n_top_defers; }
    ind(c); sb_put(&c->out, defer_exit_label(c));
    sb_put(&c->out, ": ;\n");
    for (int i = n - 1; i >= 0 && !c->error[0]; i--)
        if (arr[i] && arr[i]->go_comm) emit_stmt(c, arr[i]->go_comm);
    emit_arr_wb(c);
    if (c->cur_fn && !c->cur_fn->has_gosub)
        emit_class_locals_dtors(c);
    ind(c);
    /* `main` è `int main(...)`: un'uscita a livello di programma deve restituire un valore
     * (prima `return;` → error: non-void function 'main' should return a value, che rompeva
     * la compilazione dei sample con RETURN raggiungibile a top-level, es. ExceptionsRethrow). */
    if (cur_scope_has_gosub(c)) emit_gosub_return(c, c->cur_fn ? "return __ret;" : "return 0;");
    else sb_put(&c->out, c->cur_fn ? "return __ret;\n" : "return 0;\n");
}

/* 2.8: writeback dei parametri array BYREF (alias "_<ident>" → *<ident>, parity
 * _byRefWritebacks dell'oracolo): prima di OGNI return della procedura. */
static void emit_arr_wb(ctx_t* c) {
    fn_info_t* fn = c->cur_fn;
    if (!fn) return;
    for (int i = 0; i < fn->n_params; i++) {
        var_t* pv = vars_find(&fn->locals, fn->stmt->func_params[i]);
        if (!pv || !pv->arr_byref) continue;
        ind(c);
        sb_put(&c->out, "*"); sb_ident(&c->out, pv->name); sb_put(&c->out, " = _");
        sb_ident(&c->out, pv->name); sb_put(&c->out, "; *");
        sb_bound_ident(&c->out, pv->name, 0); sb_put(&c->out, " = _");
        sb_bound_ident(&c->out, pv->name, 0); sb_put(&c->out, ";\n");
    }
}

/* 2026-09-03: distrugge (DESTRUCTOR) le istanze di CLASSE dichiarate come locali del body
 * della funzione corrente (vclass → classe con SUB DESTRUCTOR), in ordine inverso di
 * dichiarazione — parity PCodeVM/VMC (OP_FINALIZE_SCOPE). Chiamata PRIMA del return quando
 * la funzione NON ha GOSUB (con GOSUB un return può tornare da una subroutine: la
 * finalizzazione va fatta solo nel vero exit, gestito dal chiamante). Usa gmb_obj_run_dtor
 * (no-op se l'istanza non ha dtor registrato o è nil). */
static void emit_class_locals_dtors(ctx_t* c) {
    fn_info_t* fn = c->cur_fn;
    if (!fn) return;
    for (int i = fn->locals.n - 1; i >= 0; i--) {
        var_t* lv = &fn->locals.v[i];
        if (!lv->vclass[0] || lv->is_array) continue;
        struct cls_info* ci = cls_find(c, lv->vclass);
        if (!ci || !ci->has_destructor) continue;
        ind(c);
        sb_put(&c->out, "gmb_obj_run_dtor(");
        sb_ident(&c->out, lv->name);
        sb_put(&c->out, ");\n");
    }
}
static void emit_fn_return(ctx_t* c) {
    emit_arr_wb(c);
    /* DESTRUCTOR locali di classe a ogni uscita della funzione — solo senza GOSUB
     * (con GOSUB un RETURN puo' tornare da una subroutine senza terminare la funzione). */
    if (c->cur_fn && !c->cur_fn->has_gosub)
        emit_class_locals_dtors(c);
    /* SCOPE DINAMICO: rimuove il frame della procedura a ogni uscita reale (parità emitter C#
     * gmb_dscope_pop). Saltato con GOSUB: un RETURN può essere quello della subroutine, non
     * l'uscita della funzione (stessa restrizione dei destructor locali sopra). */
    if (c->cur_fn && !cur_scope_has_gosub(c)
        && gmb_c99_list_declares_dynamic(c->cur_fn->stmt->func_body, c->cur_fn->stmt->n_funcbody)) {
        ind(c); sb_put(&c->out, "gmb_dscope_pop();\n");
    }
    ind(c);
    /* `main` è `int main(...)`: un'uscita a livello di programma deve restituire un valore
     * (prima `return;` → error: non-void function 'main' should return a value, che rompeva
     * la compilazione dei sample con RETURN raggiungibile a top-level, es. ExceptionsRethrow). */
    if (cur_scope_has_gosub(c)) emit_gosub_return(c, c->cur_fn ? "return __ret;" : "return 0;");
    else sb_put(&c->out, c->cur_fn ? "return __ret;\n" : "return 0;\n");
}

/* ─────────────────────── inferenza tipi espressioni ─────────────────────── */

static fn_info_t* find_fn(ctx_t* c, const char* name);
static int cls_inherits_named(ctx_t* c, const char* clsname, const char* target);
static int fn_ret_is_str(const fn_info_t* fn);
static int fn_ret_is_tuple(const fn_info_t* fn);
static int fn_ret_is_func(const fn_info_t* fn);
static const char* fn_ret_ctype(ctx_t* c, const fn_info_t* fn);
static void lambda_synth(ctx_t* c, gmb_expr_t* e);
int bi_is(const char* name, const char* base);

/* Pre-scan frame-propagation (parity PCodeVM): le funzioni lanciate con GO FUNCTION ...
 * INTO girano DENTRO il wrapper gmb_gofn_* che ha un setjmp attivo → un ERROR nel loro
 * body deve SOLLEVARE (gmb_raise_error), non stampare-e-basta: il wrapper lo cattura e
 * marca il future in errore, che l'awaiter rilancia nel contesto ON ERROR del chiamante. */
void gofn_err_scan(ctx_t* c, gmb_stmt_t* s) {
    if (!s) return;
    if (s->kind == GMB_STMT_GO && s->go_into && s->proc_name
        && s->proc_name->kind == GMB_EXPR_VAR && s->proc_name->var) {
        fn_info_t* tf = find_fn(c, s->proc_name->var);
        if (tf) tf->err_raise = 1;
    }
    for (int i = 0; i < s->n_then; i++) gofn_err_scan(c, s->then_body[i]);
    for (int i = 0; i < s->n_else; i++) gofn_err_scan(c, s->else_body[i]);
    for (int i = 0; i < s->n_for; i++) gofn_err_scan(c, s->for_body[i]);
    for (int i = 0; i < s->n_while; i++) gofn_err_scan(c, s->while_body[i]);
    for (int i = 0; i < s->n_do; i++) gofn_err_scan(c, s->do_body[i]);
    for (int i = 0; i < s->n_funcbody; i++) gofn_err_scan(c, s->func_body[i]);
    for (int i = 0; i < s->n_select_cases; i++)
        if (s->select_cases[i])
            for (int k = 0; k < s->select_cases[i]->n_case_body; k++)
                gofn_err_scan(c, s->select_cases[i]->case_body[k]);
}

/* Campo di variabile CATCH attiva (es. ex.Number): 0 = non è; 1 = campo numerico,
 * 2 = campo stringa (Description). NON usare TY_NUM/TY_STR: TY_NUM è 0 e si
 * confonderebbe con "non è un campo CATCH" nei test di verità. */
static int catch_member_kind(ctx_t* c, const char* var) {
    if (!var || !c->n_catch_names) return 0;
    const char* dot = strchr(var, '.');
    if (!dot) return 0;
    size_t pl = (size_t)(dot - var);
    for (int i = 0; i < c->n_catch_names; i++)
        if (strlen(c->catch_names[i]) == pl && strncasecmp(var, c->catch_names[i], pl) == 0) {
            /* Intercetta SOLO i membri-pseudo di CATCH. Un membro NON-catch (es. un CAMPO
             * della classe dell'eccezione: `ex.FieldName` di ValidationError) NON va
             * intercettato → prosegue verso l'accesso-membro normale (campo di classe). */
            int mk = gmb_member_tok(dot + 1);
            if (mk == GMB_TOK_Number || mk == GMB_TOK_LineNumber) return 1;
            if (mk == GMB_TOK_Description) return 2;
            return 0;
        }
    return 0;
}

/* Target GO FUNCTION INTO (future): indice nel registry o -1. */
static int future_index(ctx_t* c, const char* var) {
    if (!var) return -1;
    for (int i = 0; i < c->n_futures; i++)
        if (strcasecmp(var, c->future_names[i]) == 0) return i;
    return -1;
}

/* (b4): `DIM x() = NS.FN(...)` con builtin array-returning (parity oracolo
 * Statements.cs DIM-array-init). Ritorna: 0 = no; 1 = 1D flat con out-len
 * (SIGNAL.CONVOLVE/CORRELATE/HANN/HAMMING/BLACKMAN + ARRAYS.AMAP/AFILTER/
 * AREVERSE/ACLONE/AUNIQUE); 2 = matrice n×2 (ANALYSIS.FFT/IFFT). */
static int dim_arr_init_kind(const gmb_expr_t* e) {
    /* comprehension letterale LISTA `[sel FOR var IN src ...]` (ctype 0, senza annotazione
     * di tipo esplicita — dict/set hanno gia' AS DICT/HASHSET OF... che li instrada al
     * ramo GK_DICT/GK_SET generico altrove): array nativo dinamico, stesso trattamento di
     * un builtin array-returning (kind 1 = 1D flat con out-len) — bug
     * C99Native-Comprehension-DictParam-ChiaviNumeriche (AiWiki). */
    if (e && e->kind == GMB_EXPR_COMPREHENSION && e->comp_ctype == 0) return 1;
    if (!e || e->kind != GMB_EXPR_CALL || !e->var) return 0;
    /* kind per DispatchToken (chiave canonica — mai lexeme): 1 = array 1-D con out-len,
     * 2 = matrice n×2 (FFT/IFFT). Solo i token qui elencati sono gestiti in emit_dim_arr_init. */
    static const struct { gmb_tokenkind_t tk; int kind; int minargs; } k[] = {
        { GMB_TOK_SignalConvolve, 1, 2 }, { GMB_TOK_SignalCorrelate, 1, 2 },
        { GMB_TOK_SignalSavgolFilter, 1, 2 }, { GMB_TOK_SignalResample, 1, 2 },
        { GMB_TOK_SignalDecimate, 1, 2 }, { GMB_TOK_SignalFindPeaks, 1, 2 },
        { GMB_TOK_SignalFirwin, 1, 4 },
        { GMB_TOK_SignalLfilter, 1, 2 }, { GMB_TOK_SignalFiltfilt, 1, 2 }, { GMB_TOK_SignalFreqz, 1, 2 },
        { GMB_TOK_TorchShape, 1, 1 }, { GMB_TOK_TorchToArray, 1, 1 }, { GMB_TOK_TorchArgsort, 1, 1 },
        { GMB_TOK_TorchTopK, 1, 2 }, { GMB_TOK_TorchOneHot, 1, 2 }, { GMB_TOK_TorchClip, 1, 3 },
        { GMB_TOK_TorchNormalize, 1, 1 }, { GMB_TOK_TorchStandardize, 1, 1 },
        { GMB_TOK_SpatialPdist, 1, 2 }, { GMB_TOK_SpatialConvexHull, 1, 1 },
        { GMB_TOK_SignalHann, 1, 1 }, { GMB_TOK_SignalHamming, 1, 1 }, { GMB_TOK_SignalBlackman, 1, 1 },
        { GMB_TOK_Fft, 2, 1 }, { GMB_TOK_Ifft, 2, 1 },
        { GMB_TOK_FftComplex, 2, 1 }, { GMB_TOK_IfftComplex, 2, 1 },
        { GMB_TOK_FftFreq, 1, 1 }, { GMB_TOK_FftShift, 1, 1 }, { GMB_TOK_IfftShift, 1, 1 },
        { GMB_TOK_CumTrapezoid, 1, 1 }, { GMB_TOK_YuleWalker, 1, 1 },
        { GMB_TOK_MaCoefficients, 1, 1 }, { GMB_TOK_SolveOde, 1, 1 },
        { GMB_TOK_MovingAverage, 1, 1 }, { GMB_TOK_EMA, 1, 1 },
        { GMB_TOK_TsLowPass, 1, 1 }, { GMB_TOK_TsHighPass, 1, 1 },
        { GMB_TOK_TsBandPass, 1, 1 }, { GMB_TOK_TsBandStop, 1, 1 },
        { GMB_TOK_RollingMean, 1, 1 }, { GMB_TOK_RollingStdDev, 1, 1 },
        { GMB_TOK_RollingMad, 1, 1 }, { GMB_TOK_RollingZScore, 1, 1 },
        { GMB_TOK_RollingDelta, 1, 1 }, { GMB_TOK_RollingSkewness, 1, 1 },
        { GMB_TOK_RollingKurtosis, 1, 1 }, { GMB_TOK_RollingMedian, 1, 1 },
        { GMB_TOK_RollingQuantile, 1, 1 }, { GMB_TOK_RollingSharpe, 1, 1 },
        { GMB_TOK_RollingSortino, 1, 1 },
        { GMB_TOK_RollingCovariance, 1, 1 }, { GMB_TOK_RollingCorrelation, 1, 1 },
        { GMB_TOK_RollingAutocorrelation, 1, 1 },
        /* TIMESERIES matrix-returning (2026-09-18): flat + out-len → matrice [righe][cols].
         * kind 3 = matrice TS (gestita da dim_arr_timeseries_matrix). */
        { GMB_TOK_RollingRegression, 3, 3 }, { GMB_TOK_RollingRegressionSingle, 3, 2 },
        { GMB_TOK_RollingMinMax, 3, 2 }, { GMB_TOK_Decompose, 3, 2 },
        { GMB_TOK_TimeSeriesCovarianceMatrix, 3, 1 },
        { GMB_TOK_Outliers, 1, 2 },
        { GMB_TOK_Difference, 1, 1 }, { GMB_TOK_Returns, 1, 1 },
        { GMB_TOK_Deseasonalize, 1, 1 }, { GMB_TOK_TimeSeriesMinMax, 1, 1 },
        { GMB_TOK_AMap, 1, 1 }, { GMB_TOK_AFilter, 1, 1 }, { GMB_TOK_AReverse, 1, 1 },
        { GMB_TOK_ASort, 1, 1 }, { GMB_TOK_APad, 1, 2 }, { GMB_TOK_AClone, 1, 1 }, { GMB_TOK_AUnique, 1, 1 },
        { GMB_TOK_GetCursorPos, 1, 0 }, { GMB_TOK_GetTextMetrics, 1, 0 }, { GMB_TOK_GetPaletteColor, 1, 1 },
        { GMB_TOK_JarqueBeraTest, 1, 1 },
        { GMB_TOK_NelderMead, 1, 2 },
        { GMB_TOK_Bfgs, 1, 2 },
        { GMB_TOK_LBfgs, 1, 2 },
        { GMB_TOK_Broyden, 1, 2 },
        { GMB_TOK_ConjugateGradient, 1, 2 },
        { GMB_TOK_OptimizePowell, 1, 2 },
        { GMB_TOK_OptimizeFsolve, 1, 2 },
        { GMB_TOK_LevenbergMarquardt, 1, 4 },
        { GMB_TOK_LevenbergMarquardtVec, 1, 4 },
        { GMB_TOK_CurveFit, 1, 4 },
        { GMB_TOK_OptimizeBasinHopping, 1, 2 },
        { GMB_TOK_OptimizeTnc, 1, 2 }, { GMB_TOK_OptimizeCobyla, 1, 2 },
        { GMB_TOK_OptimizeSlsqp, 1, 2 }, { GMB_TOK_OptimizeMinimize, 1, 2 },
        { GMB_TOK_OptimizeBrute, 1, 2 }, { GMB_TOK_OptimizeDualAnnealing, 1, 2 },
        { GMB_TOK_DifferentialEvolution, 1, 2 },
        { GMB_TOK_OptimizeLeastSquares, 1, 2 },
        { GMB_TOK_CholeskySolve, 1, 2 }, { GMB_TOK_LeastSquares, 1, 2 },
        { GMB_TOK_Simplex, 1, 3 }, { GMB_TOK_OptimizeLinprog, 1, 3 },
        { GMB_TOK_Solve, 1, 2 }, { GMB_TOK_MatrixSolveTriangular, 1, 3 },
        { GMB_TOK_KdTreeQuery, 1, 3 }, { GMB_TOK_KdTreeQueryDist, 1, 3 },
        { GMB_TOK_KdTreeQueryBall, 1, 3 },
        { GMB_TOK_MatrixSubspaceAngles, 1, 2 },
        /* MATRIX gap 2026-09-12: HANDLE→ARRAY (runtime gmb_matrix_*_alloc con out-len) */
        { GMB_TOK_MatrixRowSums, 1, 1 }, { GMB_TOK_MatrixRowMeans, 1, 1 },
        { GMB_TOK_MatrixColSums, 1, 1 }, { GMB_TOK_MatrixColMeans, 1, 1 },
        { GMB_TOK_MatrixRowVariances, 1, 1 }, { GMB_TOK_MatrixColVariances, 1, 1 },
        { GMB_TOK_MatrixArgMax, 1, 1 }, { GMB_TOK_MatrixArgMin, 1, 1 },
        { GMB_TOK_MatrixAboveMask, 1, 2 }, { GMB_TOK_MatrixAboveMatrix, 1, 2 },
        { GMB_TOK_MatrixMultiplyVector, 1, 2 }, { GMB_TOK_MatrixMultiplyLeftVector, 1, 2 },
        /* BLOCKCHAIN: ABIDECODE(hex$, types[]) → double* + out-len (gmb_abi_decode_doubles) */
        { GMB_TOK_AbiDecode, 1, 1 },
        /* ANALYSIS array-returning (2026-09-13): IRFFT/SPLREP/SPLEV → double* + out-len */
        { GMB_TOK_FftIrfft, 1, 2 }, { GMB_TOK_InterpSplrep, 1, 2 }, { GMB_TOK_InterpSplev, 1, 2 },
    };
    for (size_t i = 0; i < sizeof(k) / sizeof(k[0]); i++)
        if (k[i].tk == e->tk && e->nargs >= k[i].minargs) return k[i].kind;
    /* letterale { e1, ..., en } (il parser lo rappresenta come CALL "_array_") */
    if (strcmp(e->var, "_array_") == 0) return 1;
    return 0;
}

/* (b4): `DIM x = NS.FN(...)` con builtin che ritorna un dict boxed in gmb_val_t
 * (parity oracolo Builtin.cs). Nota: l'oracolo non supporta l'accesso ai membri
 * (emette `if (0)`); qui i membri sono letti via gmb_val_dict_get/gmb_val_index
 * per parità con PCodeVM, che è la semantica canonica. */
static int dim_val_init_kind(const gmb_expr_t* e) {
    if (!e || e->kind != GMB_EXPR_CALL || !e->var) return 0;
    if (e->tk == GMB_TOK_KMeans) return e->nargs >= 2 ? 1 : 0;
    if (e->tk == GMB_TOK_Fetch) return e->nargs >= 1 ? 1 : 0;
    /* CHACHA20POLY1305ENCRYPT → dict val (gmb_val_t) con ciphertext/tag. */
    if (e->tk == GMB_TOK_ChaCha20Poly1305Encrypt) return 1;
    /* KEYGEN → long[] [priv, pub] (gmb_val_t lista). */
    if (e->tk == GMB_TOK_KeyGen) return 1;
    /* JSON.Parse/Load/ReadSection → oggetto JSON boxed gmb_val_t (parity emitter C#). */
    if (e->tk == GMB_TOK_Parse || e->tk == GMB_TOK_Load || e->tk == GMB_TOK_ReadSection) return 1;
    /* JSON.TOOBJECT(Tipo, json) con TARGET boxed (`DIM x AS JSON`): js_to_object emette
     * `gmb_json_parse(...)` RAW (gmb_val_t) quando cur_assign_target è boxed — stesso
     * contratto di JSON.Parse. Senza, l'assegnamento lo avvolgeva in
     * `gmb_make_val_double((gmb_double_t)(gmb_json_parse(...)))` = val→double (cc error,
     * json/toobject_boxed.bas). */
    if (e->tk == GMB_TOK_JsonToObject) return 1;
    /* CONVERT.PARSE(md$) → AST markdown boxed gmb_val_t (gmb_md_parse). */
    if (e->tk == GMB_TOK_MdParse) return 1;
    /* BLOCKCHAIN.DERIVEKEY/CONTRACT → dict boxed gmb_val_t (privateKey/publicKey/chainCode,
     * address/interface/rpcUrl). */
    if (e->tk == GMB_TOK_DeriveKey || e->tk == GMB_TOK_Contract) return 1;
    /* TRADING.PORTFOLIO: i risultati di ottimizzazione (MAXSHARPE/MEANVARIANCE/
     * MINVOLATILITY/RISKPARITY/EQUALLYWEIGHTED) e PortfolioResult (MAXRETURN/
     * KELLYCRITERION/MINCVAR/MINCDAR) sono dict boxed gmb_val_t (parity emitter C#). */
    if (e->tk == GMB_TOK_MaxSharpe || e->tk == GMB_TOK_MeanVariance
        || e->tk == GMB_TOK_MinVolatility || e->tk == GMB_TOK_RiskParity
        || e->tk == GMB_TOK_EquallyWeighted || e->tk == GMB_TOK_MaxReturn
        || e->tk == GMB_TOK_KellyCriterion || e->tk == GMB_TOK_MinCvar
        || e->tk == GMB_TOK_MinCdar) return 1;
    /* TRADING.PORTFOLIO.BLACKLITTERMAN → PortfolioResult (dict boxed gmb_val_t): il DIM/ANY
     * lo marca boxed e l'emissione è gmb_blacklitterman(...) RAW (gmb_val_t). */
    if (e->tk == GMB_TOK_BlackLitterman) return 1;
    /* TRADING.PORTFOLIO.EVOLVE → idem (il DIM lo marca già boxed; senza questa voce
     * l'assegnazione avvolgeva gmb_port_evolve in gmb_make_val_double = val→double,
     * trading.portfolio/gen_TRADING.PORTFOLIO_EVOLVE.bas). */
    if (e->tk == GMB_TOK_Evolve) return 1;
    /* TRADING.BACKTESTS.RUN(data2D, …) → BACKTESTRESULT boxed (gmb_val_t dict). Il TokenKind
     * RUN è CONDIVISO con altri domini: la forma boxed vale solo nel namespace BACKTESTS
     * (l'emissione gmb_tm_backtest_matrix lavora su un array 2-D). */
    if (e->tk == GMB_TOK_Run && e->nargs >= 1 && e->args[0] && e->ns
        && strstr(e->ns, "BACKTESTS")) return 1;
    /* STATS test d'ipotesi → dict boxed gmb_val_t (gmb_stats.c): TTEST/.../DESCRIBE.
     * Ritorna 2: boxed_val + stats_val (membri SCALARI numerici). */
    if (e->tk == GMB_TOK_TTest || e->tk == GMB_TOK_TTestPaired || e->tk == GMB_TOK_TTestOneSample
        || e->tk == GMB_TOK_StatsAnova || e->tk == GMB_TOK_Chi2Test || e->tk == GMB_TOK_FisherExact
        || e->tk == GMB_TOK_ZTest || e->tk == GMB_TOK_KolmogorovSmirnov || e->tk == GMB_TOK_ShapiroWilk
        || e->tk == GMB_TOK_NormalTest || e->tk == GMB_TOK_StatsPearsonR || e->tk == GMB_TOK_StatsSpearmanR
        || e->tk == GMB_TOK_StatsLinRegress || e->tk == GMB_TOK_StatsMannWhitney
        || e->tk == GMB_TOK_StatsWilcoxon || e->tk == GMB_TOK_StatsSkewTest
        || e->tk == GMB_TOK_StatsKurtosisTest || e->tk == GMB_TOK_StatsJarqueBera
        || e->tk == GMB_TOK_StatsDescribe || e->tk == GMB_TOK_StatsChi2Contingency) return 2;
    /* letterale tupla (a, b, ...) → gmb_val_tuple, gmb_val_t boxed (vedi emit_tuple_lit). */
    if (strcmp(e->var, "_tuple_lit_") == 0) return 1;
    /* Costruttori COLLEZIONE/oggetto che emettono GIÀ un gmb_val_t: NEW LIST/DICT/SET/…
     * (var "*OF:" o "COLLNEW…") e i _new_json_/_new_httpconfig_/_new_httpoptions_/
     * _new_cookiejar_. Devono essere assegnati RAW a una var boxed (non avvolti in
     * gmb_make_val_double: cast val→double, cc error). */
    if (!strncmp(e->var, "LISTOF:", 7) || !strncmp(e->var, "DICTOF:", 7)
        || !strncmp(e->var, "SETOF:", 7) || !strncmp(e->var, "HASHOF:", 7)
        || !strncmp(e->var, "COLLNEW", 7)) return 1;
    if (!strcmp(e->var, "_new_json_") || !strcmp(e->var, "_new_httpconfig_")
        || !strcmp(e->var, "_new_httpoptions_") || !strcmp(e->var, "_new_cookiejar_")) return 1;
    return 0;
}

static int boxed_member_is_str(const char* m);

/* 2.7: classi — lookup e accesso campi (parity oracolo C99CodeEmitter.cs:527+ /
 * Partial/C99CodeEmitter.Classes.cs). Le istanze sono gmb_val_t boxed:
 * v_ptr → gmb_obj_t → data → struct gmb_obj_<Classe>. */
static struct cls_info* cls_specialize(ctx_t* c, const char* name);
/* Non-static: condivisa con gmb_c99_emit_speed.c (§0quater). */
struct cls_info* cls_find(ctx_t* c, const char* name) {
    if (!name) return NULL;
    for (int i = 0; i < c->n_classes; i++)
        if (strcasecmp(c->classes[i].name, name) == 0) return &c->classes[i];
    /* tipo GENERICO istanziato `Base<A1,A2>`: crea/ritrova la specializzazione. */
    if (strchr(name, '<')) { struct cls_info* sp = cls_specialize(c, name); if (sp) return sp; }
    /* Nome QUALIFICATO (es. "MVC.HttpController" da `INHERITS MVC.HttpController`): il registro
     * classi del frontend usa il nome NUDO → riprova con l'ULTIMO segmento. Senza, l'intera
     * ereditarietà cross-modulo (framework MVC) non era risolta: `cls_emit_flat_fields` non
     * includeva i campi EREDITATI nella struct del derivato (ArticoliController = 4 byte invece
     * dei 32 di Request+Response) e `SetContext` scriveva oltre l'allocazione → heap corruption
     * → SIGSEGV dentro malloc (crash del server MVC alla prima richiesta). */
    if (strchr(name, '.')) {
        const char* last = strrchr(name, '.');
        if (last && last[1])
            for (int i = 0; i < c->n_classes; i++)
                if (strcasecmp(c->classes[i].name, last + 1) == 0) return &c->classes[i];
    }
    return NULL;
}
/* Specializza un tipo generico `Base<A1,A2,...>` (parità C#: `Pair<INTEGER,STRING>` →
 * `gmb_udt_Pair_INTEGER_STRING_`): crea una cls_info con nome SANIFICATO (Base_A1_A2_) e i
 * campi della base con i type-param SOSTITUITI. Cache: se già esiste ritorna quella. NULL se
 * la base non è un generico (nessun `type_params`). */
static struct cls_info* cls_specialize(ctx_t* c, const char* name) {
    const char* lt = strchr(name, '<');
    if (!lt) return NULL;
    size_t bl = (size_t)(lt - name);
    if (bl < 1 || bl >= 40) return NULL;
    char base[40]; memcpy(base, name, bl); base[bl] = 0;
    { const char* last = strrchr(base, '.'); if (last && last[1]) { size_t ol = strlen(last + 1); memmove(base, last + 1, ol + 1); } }
    /* nome sanificato `Base_A1_A2_` */
    char sname[80]; size_t sp = 0;
    for (const char* p = name; *p && sp < sizeof sname - 2; p++) {
        char ch = *p;
        if (ch == '<' || ch == '>' || ch == ',' || ch == ' ') { if (sp && sname[sp - 1] != '_') sname[sp++] = '_'; }
        else sname[sp++] = ch;
    }
    if (sp && sname[sp - 1] != '_') sname[sp++] = '_';
    sname[sp] = 0;
    for (int i = 0; i < c->n_classes; i++) if (strcasecmp(c->classes[i].name, sname) == 0) return &c->classes[i];
    struct cls_info* bc = cls_find(c, base);
    if (!bc || !bc->type_params[0] || c->n_classes >= 256) return NULL;
    /* parse dei type-param della base e degli argomenti dell'istanza */
    char bp[8][40]; int nbp = 0;
    { const char* r = bc->type_params; while (*r && nbp < 8) { const char* e = strchr(r, ','); size_t l = e ? (size_t)(e - r) : strlen(r); if (l >= 40) l = 39; memcpy(bp[nbp], r, l); bp[nbp][l] = 0; nbp++; r = e ? e + 1 : r + l; } }
    char ag[8][40]; int nag = 0;
    { const char* r = lt + 1; while (*r && *r != '>' && nag < 8) { const char* e = r; while (*e && *e != ',' && *e != '>') e++; size_t l = (size_t)(e - r); while (l && *r == ' ') { r++; l--; } while (l && r[l - 1] == ' ') l--; if (l >= 40) l = 39; memcpy(ag[nag], r, l); ag[nag][l] = 0; nag++; r = (*e == ',') ? e + 1 : e; } }
    struct cls_info* ci = &c->classes[c->n_classes++];
    memset(ci, 0, sizeof(*ci));
    snprintf(ci->name, 40, "%s", sname);
    snprintf(ci->base, 40, "%s", bc->base);
    ci->is_interface = bc->is_interface; ci->is_udt = bc->is_udt; ci->is_packed = bc->is_packed;
    for (int i = 0; i < bc->nimpl && ci->nimpl < 8; i++) snprintf(ci->impl[ci->nimpl++], 40, "%s", bc->impl[i]);
    for (int i = 0; i < bc->nfields && ci->nfields < 128; i++) {
        snprintf(ci->fname[ci->nfields], 40, "%s", bc->fname[i]);
        char ft[40]; snprintf(ft, sizeof ft, "%s", bc->ftype[i]);
        for (int p = 0; p < nbp && p < nag; p++) {
            size_t pl = strlen(bp[p]);
            char* hit = ft;
            while ((hit = strstr(hit, bp[p])) != NULL) {
                char tmp[40]; size_t pre = (size_t)(hit - ft);
                snprintf(tmp, sizeof tmp, "%.*s%s%s", (int)pre, ft, ag[p], hit + pl);
                snprintf(ft, sizeof ft, "%s", tmp);
                hit = ft + pre + strlen(ag[p]);
            }
        }
        snprintf(ci->ftype[ci->nfields], 40, "%s", ft);
        ci->nfields++;
    }
    return ci;
}
/* True se il nome di tipo DICHIARATO è un VAL OPACO (dict/HTTP/JSON): a runtime è un
 * gmb_val_t. Unica fonte per campi di classe e tipi di ritorno (parità col mapping dei
 * parametri e dei DIM, che già usano gmb_val_t per questi tipi). */
static int decl_is_opaque_val(const char* tn) {
    return tn && (!strcasecmp(tn, "HTTPRESPONSE") || !strcasecmp(tn, "HTTPREQUEST")
        || !strcasecmp(tn, "JSON") || !strcasecmp(tn, "DECISION") || !strcasecmp(tn, "ANY") || !strcasecmp(tn, "VARIANT")
        || !strcasecmp(tn, "FETCHRESULT") || !strcasecmp(tn, "HTTPOPTIONS")
        || !strcasecmp(tn, "HTTPHEADERS") || !strcasecmp(tn, "HTTPCONFIG")
        || !strcasecmp(tn, "HTTPPOSTEDDATA") || !strcasecmp(tn, "WEBSOCKET"));
}
static const char* cls_field_ctype(ctx_t* c, const char* tn) {
    /* Campo-ARRAY di classe (parser: tipo marcato con suffisso "[]", es. "INTEGER[]"):
     * la struct C lo dichiara come PUNTATORE all'elemento (parity emitter C#
     * MapType(ArrayType) == Elem*). Prima ricadeva a gmb_double_t scalare → 'SELF.arr'
     * non era indicizzabile. Deve precedere il match STRING (tn "STRING[]" matcha "STRING"). */
    if (tn && tn[0]) {
        size_t tl = strlen(tn);
        if (tl >= 2 && tn[tl - 1] == ']' && strchr(tn, '[')) {
            /* Elemento dal nome base (senza "[N]"): se è un TYPE/CLASS → struct C di quel tipo
             * (array di UDT: `arr(i).campo`); altrimenti scalare. */
            char _eb[64]; const char* _lb = strchr(tn, '[');
            size_t _bl = (size_t)(_lb - tn); if (_bl > 63) _bl = 63;
            memcpy(_eb, tn, _bl); _eb[_bl] = 0;
            if (strncasecmp(_eb, "STRING", 6) == 0) return "gmb_string_t*";
            if (gmb_ctype_is_list(_eb)) return "gmb_list_t*";
            struct cls_info* _ne = cls_find(c, _eb);
            if (_ne) {
                static char _nb[8][48]; static int _nbi = 0;
                char* _o = _nb[_nbi]; _nbi = (_nbi + 1) % 8;
                snprintf(_o, 48, "gmb_obj_%s*", _ne->name);
                return _o;
            }
            return "gmb_double_t*";
        }
    }
    if (tn && gmb_keyword_tok(tn) == GMB_TOK_StringType) return "gmb_string_t";
    /* `STRING * N` (lunghezza fissa, conservata dal parser per DBF/ISAM): gmb_keyword_tok non
     * riconosce la stringa con il suffisso → senza questo confronto il campo diventava
     * gmb_double_t e l'assegnazione di una stringa non compilava. */
    if (tn && strncasecmp(tn, "STRING", 6) == 0) return "gmb_string_t";
    if (tn && (gmb_ctype_is_list(tn))) return "gmb_list_t";
    /* Campo UDT annidato (bug UDT-Campo-Annidato): se `tn` nomina un altro TYPE (is_udt), il
     * campo è la struct C di quel TYPE, EMBEDDED per valore (mai gmb_double_t) — senza questo,
     * la struct C non allocava spazio reale per il campo annidato (finiva a 0.0 silenziosamente,
     * o l'accesso a catena "o.I.X" non compilava perché il campo I non era una struct). */
    if (tn) {
        struct cls_info* nested = cls_find(c, tn);
        if (nested && nested->is_udt) {
            static char nbuf[8][48]; static int nbuf_i = 0;
            char* out = nbuf[nbuf_i]; nbuf_i = (nbuf_i + 1) % 8;
            snprintf(out, 48, "gmb_obj_%s", nested->name);
            return out;
        }
    }
    /* Campo DICT-OPACO (HTTPRESPONSE/HTTPREQUEST/JSON/ANY/…): a runtime è un gmb_val_t.
     * Senza, la struct C lo dichiarava gmb_double_t → `SELF.Response = res` e
     * `SELF.Response.StatusCode = 404` davano "assigning to 'gmb_double_t' from incompatible
     * type 'gmb_val_t'" (sample MVC). */
    if (decl_is_opaque_val(tn)) return "gmb_val_t";
    return "gmb_double_t";
}
/* Dimensione (slot) di un campo-array di classe dal tipo marcato dal parser "Elem[N]"
 * (N = limite superiore 0-based) → N+1. -1 se non è un campo-array. */
int cls_field_arr_size(const char* tn) {
    if (!tn) return -1;
    const char* lb = strchr(tn, '[');
    if (!lb) return -1;
    size_t tl = strlen(tn);
    if (tl == 0 || tn[tl - 1] != ']') return -1;
    /* MULTI-dim ("INTEGER[2][2]"): prodotto dei bound+1 di TUTTE le dim (parity DIM locale,
     * `DIM m(2,2)` → 9 slot). Prima assumeva una sola dim → allocazione 3 su un accesso
     * flat fino a 8 (SIGSEGV). */
    long prod = 1; int any = 0;
    for (const char* q = lb; *q; q++) {
        if (*q == '[') {
            long n = strtol(q + 1, NULL, 10);
            prod *= (n + 1); any = 1;
            const char* rb = strchr(q, ']');
            if (!rb) break;
            q = rb;
        }
    }
    return any ? (int)prod : -1;
}
/* Bound (limite SUPERIORE dichiarato) della d-esima dim di un campo-array multi-dim:
 * da "INTEGER[2][2]" → cls_field_arr_dim(tn,1) = 2. Per la scrittura flat di `m(i,j)`. */
long cls_field_arr_dim(const char* tn, int d) {
    if (!tn) return 0;
    const char* q = strchr(tn, '[');
    int k = 0;
    while (q && *q) {
        if (*q == '[') {
            if (k == d) return strtol(q + 1, NULL, 10);
            k++;
            const char* rb = strchr(q, ']');
            if (!rb) break;
            q = rb + 1;
        } else q++;
    }
    return 0;
}
/* Alloca i campi-ARRAY di una classe (parity emitter C# gmb_user_<Cls>_init_fields):
 * inst_expr è un'espressione C di tipo gmb_obj_<ci->name>*. Senza, `arr(i)` scrive su un
 * puntatore NULL. */
static void cls_emit_arr_alloc(ctx_t* c, struct cls_info* ci, const char* inst_expr) {
    for (int k = 0; k < ci->nfields; k++) {
        int sz = cls_field_arr_size(ci->ftype[k]);
        if (sz < 0) continue;
        const char* ec = cls_field_ctype(c, ci->ftype[k]);   /* "gmb_double_t*" */
        char elem[80];
        snprintf(elem, sizeof(elem), "%s", ec);
        size_t el = strlen(elem);
        if (el && elem[el - 1] == '*') elem[el - 1] = 0;
        ind(c);
        sb_printf(&c->out, "%s->", inst_expr);
        sb_ident(&c->out, ci->fname[k]);
        sb_printf(&c->out, " = (%s*)calloc((size_t)%d, sizeof(%s));\n", ec, sz, elem);
    }
}
/* stringa del tipo dichiarato di un campo della classe (NULL se assente) */
const char* cls_field_type_of(struct cls_info* ci, const char* f) {
    for (int i = 0; i < ci->nfields; i++)
        if (strcasecmp(ci->fname[i], f) == 0) return ci->ftype[i];
    return NULL;
}
/* True se `name` è un PARAMETRO della funzione corrente (può ombreggiare un campo). */
static int cur_fn_is_param(ctx_t* c, const char* name) {
    if (!c->cur_fn || !c->cur_fn->stmt || !name) return 0;
    gmb_stmt_t* fs = c->cur_fn->stmt;
    for (int i = 0; i < fs->n_params; i++)
        if (fs->func_params[i] && strcasecmp(fs->func_params[i], name) == 0) return 1;
    return 0;
}
/* True se `name` è un campo SCALARE della classe della funzione corrente e NON è ombreggiato
 * da un DIM locale o da un parametro: allora un uso NUDO (`v`, non `SELF.v`) va reso come
 * `SELF.<name>`. Prima il nome nudo era registrato come LOCALE dallo scope scan → la scrittura
 * non persisteva nel campo (bug Class-Bare-Scalar-Member-Trattato-Come-Locale). */
static int cur_fn_bare_class_field(ctx_t* c, const char* name) {
    if (!c->cur_fn || !c->cur_fn->cls_owner[0] || !name || !name[0] || strchr(name, '.')) return 0;
    struct cls_info* ci = cls_find(c, c->cur_fn->cls_owner);
    if (!ci || !cls_field_type_of(ci, name)) return 0;
    if (cur_fn_is_param(c, name)) return 0;
    var_t* lv = vars_find(&c->cur_fn->locals, name);
    if (lv && lv->is_dim_local) return 0;
    return 1;
}
/* catena di accesso al campo: ((gmb_obj_<C>*)(((gmb_obj_t*)<base>.v_ptr)->data))-><field>
 * <base> è l'espressione istanza ("p", "(*self)", ...)
 * Non-static: condivisa con gmb_c99_emit_speed.c (§0quater). */
void sb_cls_field(sb_t* b, struct cls_info* ci, const char* base, const char* field) {
    sb_printf(b, "((gmb_obj_%s*)(((gmb_obj_t*)%s.v_ptr)->data))->", ci->name, base);
    sb_ident(b, field);
}
static int cls_field_exists(struct cls_info* ci, const char* f) {
    for (int i = 0; i < ci->nfields; i++) if (strcasecmp(ci->fname[i], f) == 0) return 1;
    return 0;
}
/* Non-static: condivisa con gmb_c99_emit_speed.c (§0quater). */
int cls_field_is_str(struct cls_info* ci, const char* f) {
    for (int i = 0; i < ci->nfields; i++)
        if (strcasecmp(ci->fname[i], f) == 0) {
            return strncasecmp(ci->ftype[i], "STRING", 6) == 0;
        }
    return 0;
}
/* Lunghezza fissa N da un tipo campo "STRING * N" (0 se non a lunghezza fissa).
 * Serve per paddare/truncare a N nell'assegnazione a un campo UDT (parità con
 * IL/PCode/VM-C, dove `STRING * N` è a lunghezza fissa — vedi MiniTests/speed/set_filter.bas). */
int cls_field_fixed_len(struct cls_info* ci, const char* f) {
    for (int i = 0; i < ci->nfields; i++) {
        if (strcasecmp(ci->fname[i], f) == 0) {
            const char* star;
            if (strncasecmp(ci->ftype[i], "STRING", 6) != 0) return 0;
            star = strchr(ci->ftype[i], '*');
            return star ? atoi(star + 1) : 0;
        }
    }
    return 0;
}
/* 2.7(d): campo STATIC — cerca in <clsname> e poi lungo la catena base (i campi
 * statici sono condivisi, accessibili anche via classe derivata). */
static struct cls_info* cls_static_find(ctx_t* c, const char* clsname, const char* f, int* idx) {
    const char* w = clsname;
    for (int d = 0; d < 8 && w && w[0]; d++) {
        struct cls_info* ci = cls_find(c, w);
        if (!ci) return NULL;
        for (int k = 0; k < ci->nstatics; k++)
            if (strcasecmp(ci->sname[k], f) == 0) { if (idx) *idx = k; return ci; }
        w = ci->base;
    }
    return NULL;
}
/* 2.7(c): classe che DEFINISCE il campo lungo la catena INHERITS (base-first nel
 * layout flat, parity oracolo FieldsWithBase) — il cast va fatto sulla struct
 * della classe definente (layout-compatibile: i campi base sono il prefisso). */
static struct cls_info* cls_field_owner(ctx_t* c, const char* clsname, const char* f) {
    for (int d = 0; d < 8 && clsname; d++) {
        struct cls_info* ci = cls_find(c, clsname);
        if (!ci) {
            /* Base QUALIFICATA (es. MVC.HttpController): il registro classi del frontend usa il
             * nome NUDO → riprova col segmento finale. Senza, l'ereditarietà cross-modulo (MVC)
             * non era risolta: `SELF.Response` (campo della base) non veniva trovato. */
            const char* lastdot = strrchr(clsname, '.');
            if (lastdot && lastdot[1]) { ci = cls_find(c, lastdot + 1); clsname = lastdot + 1; }
            if (!ci) return NULL;
        }
        if (cls_field_exists(ci, f)) return ci;
        clsname = ci->base[0] ? ci->base : NULL;
    }
    return NULL;
}
/* Naviga una catena di campo UDT annidato "I.X.Y..." (bug UDT-Campo-Annidato, C99Native):
 * consuma tutti i segmenti TRANNE l'ultimo, che devono essere campi UDT DIRETTI (gli UDT
 * semplici sono struct C per valore: nessuna property in mezzo, a differenza delle classi).
 * Ad ogni segmento consumato estende `base` con ".segmento" e aggiorna `*ci_inout` al cls_info
 * del tipo del campo. Ritorna il puntatore al segmento FINALE (nel buffer statico interno) da
 * risolvere col comportamento esistente (campo/property sull'owner aggiornato). Se un segmento
 * intermedio non è un campo UDT diretto risolvibile, ritorna `chain` invariata e lascia
 * `*ci_inout`/`base` invariati: fallback al comportamento preesistente (mai una regressione). */
static const char* resolve_nested_udt_chain(ctx_t* c, struct cls_info** ci_inout, char* base, size_t base_sz, const char* chain, int* out_landed) {
    static char buf[256];
    *out_landed = 0;
    size_t cl = strlen(chain);
    if (cl >= sizeof(buf)) return chain;
    memcpy(buf, chain, cl + 1);
    struct cls_info* ci = *ci_inout;
    struct cls_info* start_ci = ci;
    char start_base[200]; snprintf(start_base, sizeof(start_base), "%s", base);
    char* seg = buf;
    int first = 1;   /* il PRIMO campo attraversa v_ptr->data (sb_cls_field); i successivi sono
                       * struct-in-struct per valore (embedded, cls_field_ctype) → ".campo" diretto */
    for (;;) {
        char* dot = strchr(seg, '.');
        if (!dot) { *ci_inout = ci; *out_landed = !first; return seg; }   /* ultimo segmento: risolto dal chiamante */
        *dot = 0;
        struct cls_info* fo = ci ? cls_field_owner(c, ci->name, seg) : NULL;
        /* ftype[] è il nome RAW del tipo BASIC del campo (es. "Inner"), non un C-type
         * prefissato: un campo è UDT annidato se quel nome risolve a un TYPE (is_udt=1),
         * gli unici rappresentati come struct C per valore accessibili con "base.campo". */
        const char* fty = fo ? cls_field_type_of(fo, seg) : NULL;
        struct cls_info* next_ci = fty ? cls_find(c, fty) : NULL;
        if (!fo || !next_ci || !next_ci->is_udt) { *ci_inout = start_ci; snprintf(base, base_sz, "%s", start_base); return chain; }
        if (first) {
            sb_t tmp; memset(&tmp, 0, sizeof(tmp));
            sb_cls_field(&tmp, fo, base, seg);
            snprintf(base, base_sz, "%s", tmp.s ? tmp.s : "");
            free(tmp.s);
            first = 0;
        } else {
            size_t bl = strlen(base);
            snprintf(base + bl, base_sz - bl, ".%s", seg);
        }
        ci = next_ci;
        seg = dot + 1;
    }
}
/* Accesso al campo FINALE di una catena risolta da resolve_nested_udt_chain: se `landed` (la
 * catena ha attraversato almeno un livello annidato), `base` è già un'espressione C che designa
 * una struct EMBEDDED per valore → "base.campo" diretto (mai un altro cast v_ptr/data). Se non
 * landed (caso base, un solo livello, comportamento preesistente) → sb_cls_field normale. */
static void sb_udt_field_access(sb_t* b, struct cls_info* ci, const char* base, const char* field, int landed) {
    if (landed) {
        sb_put(b, base);
        sb_put(b, ".");
        sb_ident(b, field);
    } else {
        sb_cls_field(b, ci, base, field);
    }
}
/* lookup metodo della classe per nome (dispatch STATICO, parity oracolo) */
static fn_info_t* cls_find_method(ctx_t* c, const char* clsname, const char* meth);
/* 2.7(b): nome sintetico dell'accessore di property (buffer statico, non rientrante) */
static const char* prop_accessor_name(const char* prop, const char* kind) {
    static char pabuf[160];
    snprintf(pabuf, sizeof(pabuf), "%s_%s", kind, prop);
    return pabuf;
}
static fn_info_t* cls_find_method(ctx_t* c, const char* clsname, const char* meth) {
    for (int i = 0; i < c->nfn; i++)
        if (c->fns[i].cls_owner[0] && strcasecmp(c->fns[i].cls_owner, clsname) == 0 &&
            c->fns[i].stmt->func_name && strcasecmp(c->fns[i].stmt->func_name, meth) == 0)
            return &c->fns[i];
    return NULL;
}
/* 2.7(c): metodo lungo la catena INHERITS (la classe derivata vince = OVERRIDE;
 * il nome C usa mf->cls_owner, parity oracolo dispatch statico+linker) */
static fn_info_t* cls_find_method_chain(ctx_t* c, const char* clsname, const char* meth) {
    for (int d = 0; d < 8 && clsname; d++) {
        /* Normalizza SEMPRE il nome via cls_find: la base è memorizzata QUALIFICATA
         * (`INHERITS Mezzi.Veicolo`) ma i metodi sono registrati col nome NUDO della classe
         * (`Veicolo`). Senza normalizzare, `cls_find_method("Mezzi.Veicolo", meth)` non trovava
         * i metodi ereditati cross-file ("metodo 'Accelera' non definito nella classe Auto"). */
        struct cls_info* ci = cls_find(c, clsname);
        fn_info_t* mf = cls_find_method(c, ci ? ci->name : clsname, meth);
        if (mf) return mf;
        clsname = (ci && ci->base[0]) ? ci->base : NULL;
    }
    return NULL;
}
/* True se la classe (o una sua base) è `Control` (namespace CONTROLS) — per lo zucchero
 * `istanza.Move/SetFocus/ZOrder/Invalidate/Refresh(...)` → comando `CONTROL ...` (§11.7). */
static int cls_inherits_control(ctx_t* c, const char* clsname) {
    for (int d = 0; d < 8 && clsname; d++) {
        if (!strcasecmp(clsname, "Control")) return 1;
        struct cls_info* ci = cls_find(c, clsname);
        clsname = (ci && ci->base[0]) ? ci->base : NULL;
    }
    return 0;
}
/* §11.1: nome-proprietà runtime per CONTROL GET/SET (NULL se non è una proprietà controllo). */
