static void em_msg_str(ctx_t* c, gmb_expr_t* e);
/* MESSAGE (namespace MESSAGE): bus in-process (gmb_msg_*). */
static void em_msg_str(ctx_t* c, gmb_expr_t* e){ if(e){ emit_str_operand(c,e); sb_put(&c->out, ".data"); } else sb_put(&c->out, "\"\""); }
static void st_message(ctx_t* c, gmb_stmt_t* s)
{
    const char* v = s->mutex_action ? s->mutex_action : "";
    ind(c);
    if (strcmp(v, "CONNECT") == 0) {
        if (s->target_label) { sb_ident(&c->out, s->target_label); sb_put(&c->out, " = "); }
        sb_put(&c->out, "gmb_msg_connect("); em_msg_str(c, s->net_args ? s->net_args[0] : NULL); sb_put(&c->out, ");\n");
        if (s->target_label) { ind(c); sb_put(&c->out, "gmb_msg_start_recv((int64_t)("); sb_ident(&c->out, s->target_label); sb_put(&c->out, "));\n"); }
    } else if (strcmp(v, "SUBSCRIBE") == 0) {
        sb_put(&c->out, "gmb_msg_subscribe((int64_t)(");
        if (s->net_args && s->net_args[0]) emit_expr(c, s->net_args[0]); else sb_put(&c->out, "0");
        sb_put(&c->out, "), "); em_msg_str(c, (s->n_netargs > 1) ? s->net_args[1] : NULL);
        sb_put(&c->out, ", "); em_msg_str(c, (s->n_netargs > 3) ? s->net_args[3] : NULL);
        sb_put(&c->out, ");\n");
    } else if (strcmp(v, "UNSUBSCRIBE") == 0) {
        sb_put(&c->out, "gmb_msg_unsubscribe("); em_msg_str(c, (s->n_netargs > 0) ? s->net_args[0] : NULL); sb_put(&c->out, ");\n");
    } else if (strcmp(v, "PUBLISH") == 0) {
        sb_put(&c->out, "gmb_msg_publish((int64_t)(");
        if (s->net_args && s->net_args[0]) emit_expr(c, s->net_args[0]); else sb_put(&c->out, "0");
        sb_put(&c->out, "), "); em_msg_str(c, (s->n_netargs > 1) ? s->net_args[1] : NULL);
        sb_put(&c->out, ", "); em_msg_str(c, (s->n_netargs > 2) ? s->net_args[2] : NULL);
        sb_put(&c->out, ");\n");
    } else {
        sb_put(&c->out, strcmp(v, "CLOSE") == 0 ? "gmb_msg_close((int64_t)(" : "gmb_msg_ping((int64_t)(");
        if (s->n_netargs > 0 && s->net_args[0]) emit_expr(c, s->net_args[0]); else sb_put(&c->out, "0");
        sb_put(&c->out, "));\n");
    }
}
/* Bersaglio-C di un evento: label di MODULO -> funzione lfn_<nome> (parity _moduleNamedLabels);
 * altrimenti SUB -> gmb_user_<nome>. */
static void emit_event_target(ctx_t* c, const char* name)
{
    if (!name || !*name) { sb_put(&c->out, "0"); return; }
    sb_put(&c->out, "(gmb_form_cb)gmb_user_"); sb_ident(&c->out, name);
}
static int event_target_is_sub(ctx_t* c, const char* name)
{
    if (!name || !*name) return 0;
    for (int k = 0; k < c->nfn; k++) {
        const char* fn = c->fns[k].stmt->func_name;
        if (!fn) continue;
        const char* x = name; const char* y = fn; int ok = 1;
        while (*x || *y) { if (*x == '_') { x++; continue; } if (*y == '_') { y++; continue; }
            if (tolower((unsigned char)*x) != tolower((unsigned char)*y)) { ok = 0; break; } x++; y++; }
        if (ok) return 1;
    }
    return 0;
}
static void st_on_control_event(ctx_t* c, gmb_stmt_t* s)
{
    if (s->flag != 2 && s->target_label && !event_target_is_sub(c, s->target_label))
    { c99_fail(c, s->line, "Evento controllo: il gestore deve essere una SUB (non un label)"); return; }
    c99_mark_tui(c);
    ind(c);
    sb_put(&c->out, "gmb_form_set_event_id((int)(");
    if (s->on_expr) emit_expr(c, s->on_expr); else sb_put(&c->out, "-1");
    sb_put(&c->out, "), gmb_form_ev_index(\"");
    if (s->ce_event) for (const char* q = s->ce_event; *q; q++) { char ch[2] = { *q, 0 }; sb_put(&c->out, ch); }
    sb_put(&c->out, "\"), ");
    if (s->flag == 2) sb_put(&c->out, "NULL");
    else emit_event_target(c, s->target_label);
    sb_put(&c->out, ");\n");
}
static void st_on_message(ctx_t* c, gmb_stmt_t* s)
{
    const char* h = s->target_label ? s->target_label : "";
    if (h[0]) {
        int i, seen = 0;
        for (i = 0; i < c->n_msg_done; i++) if (strcmp(c->msg_done[i], h) == 0) { seen = 1; break; }
        if (!seen && c->n_msg_done < 16) {
            snprintf(c->msg_done[c->n_msg_done], sizeof(c->msg_done[0]), "%s", h); c->n_msg_done++;
            sb_put(&c->msg_wraps, "static void _gmb_msgcb_"); sb_ident(&c->msg_wraps, h);
            sb_put(&c->msg_wraps, "(const char* _id, const char* _t, const char* _d) { gmb_user_"); sb_ident(&c->msg_wraps, h);
            sb_put(&c->msg_wraps, "(gmb_string_alloc(_id), gmb_string_alloc(_t), gmb_string_alloc(_d)); }\n");
        }
    }
    if (s->flag != 0) return;
    ind(c);
    sb_put(&c->out, "gmb_msg_reg_handler(");
    em_msg_str(c, (s->n_netargs > 0) ? s->net_args[0] : NULL);
    sb_put(&c->out, ", _gmb_msgcb_"); sb_ident(&c->out, h); sb_put(&c->out, ");\n");
}
/* SEGNALI (namespace SIGNAL): bus locale con filtro strutturato (gmb_signal_*). */
static void st_signal(ctx_t* c, gmb_stmt_t* s)
{
    const char* v = s->mutex_action ? s->mutex_action : "";
    ind(c);
    if (strcmp(v, "SUBSCRIBE") == 0) {
        /* gmb_signal_subscribe(id, types, asset, market, symbols, timeframe) */
        sb_put(&c->out, "gmb_signal_subscribe(");
        em_msg_str(c, (s->n_netargs > 5) ? s->net_args[5] : NULL); sb_put(&c->out, ", ");
        em_msg_str(c, (s->n_netargs > 0) ? s->net_args[0] : NULL); sb_put(&c->out, ", ");
        em_msg_str(c, (s->n_netargs > 1) ? s->net_args[1] : NULL); sb_put(&c->out, ", ");
        em_msg_str(c, (s->n_netargs > 2) ? s->net_args[2] : NULL); sb_put(&c->out, ", ");
        em_msg_str(c, (s->n_netargs > 3) ? s->net_args[3] : NULL); sb_put(&c->out, ", ");
        em_msg_str(c, (s->n_netargs > 4) ? s->net_args[4] : NULL);
        sb_put(&c->out, ");\n");
    } else if (strcmp(v, "EMIT") == 0) {
        /* gmb_signal_emit(type, symbol, value, asset, market, timeframe) */
        sb_put(&c->out, "gmb_signal_emit(");
        em_msg_str(c, (s->n_netargs > 0) ? s->net_args[0] : NULL); sb_put(&c->out, ", ");
        em_msg_str(c, (s->n_netargs > 1) ? s->net_args[1] : NULL); sb_put(&c->out, ", ");
        sb_put(&c->out, "(double)(");
        if (s->n_netargs > 2 && s->net_args[2]) emit_expr(c, s->net_args[2]); else sb_put(&c->out, "0.0");
        sb_put(&c->out, "), ");
        em_msg_str(c, (s->n_netargs > 3) ? s->net_args[3] : NULL); sb_put(&c->out, ", ");
        em_msg_str(c, (s->n_netargs > 4) ? s->net_args[4] : NULL); sb_put(&c->out, ", ");
        em_msg_str(c, (s->n_netargs > 5) ? s->net_args[5] : NULL);
        sb_put(&c->out, ");\n");
    } else if (strcmp(v, "UNSUBSCRIBE") == 0) {
        sb_put(&c->out, "gmb_signal_unsubscribe(");
        em_msg_str(c, (s->n_netargs > 0) ? s->net_args[0] : NULL);
        sb_put(&c->out, ");\n");
    } else if (strcmp(v, "PING") == 0) {
        sb_put(&c->out, "gmb_signal_ping();\n");
    } else {
        c99_fail(c, s->line, "SIGNAL: verbo '%s' non supportato", v);
    }
}
/* ON SIGNAL <id> CALL <handler>: wrapper tipizzato sull'arità della SUB (4 = senza
 * timeframe, 5 = con timeframe) e registrazione su gmb_signal_on. STOP = disattiva. */
static void st_on_signal(ctx_t* c, gmb_stmt_t* s)
{
    const char* h = s->target_label ? s->target_label : "";
    if (s->flag == 2) {   /* STOP */
        ind(c);
        sb_put(&c->out, "gmb_signal_on(");
        em_msg_str(c, (s->n_netargs > 0) ? s->net_args[0] : NULL);
        sb_put(&c->out, ", NULL, NULL);\n");
        return;
    }
    if (s->flag != 0) { c99_fail(c, s->line, "ON SIGNAL: azione non supportata (solo CALL e STOP)"); return; }
    if (!h[0]) { c99_fail(c, s->line, "ON SIGNAL: manca il nome dell'handler"); return; }
    {
        fn_info_t* f = find_fn(c, h);
        int npar = f ? f->n_params : 4;
        char key[160]; int i, seen = 0;
        snprintf(key, sizeof(key), "S%s", h);
        for (i = 0; i < c->n_msg_done; i++) if (strcmp(c->msg_done[i], key) == 0) { seen = 1; break; }
        if (!seen && c->n_msg_done < 16) {
            snprintf(c->msg_done[c->n_msg_done], sizeof(c->msg_done[0]), "%s", key); c->n_msg_done++;
            sb_put(&c->msg_wraps, "static void _gmb_sigcb_"); sb_ident(&c->msg_wraps, h);
            if (npar >= 5) {
                sb_put(&c->msg_wraps, "(const char* _id, const char* _t, const char* _s, double _v, const char* _tf) { gmb_user_");
                sb_ident(&c->msg_wraps, h);
                sb_put(&c->msg_wraps, "(gmb_string_alloc(_id), gmb_string_alloc(_t), gmb_string_alloc(_s), (gmb_double_t)_v, gmb_string_alloc(_tf)); }\n");
            } else {
                sb_put(&c->msg_wraps, "(const char* _id, const char* _t, const char* _s, double _v) { gmb_user_");
                sb_ident(&c->msg_wraps, h);
                sb_put(&c->msg_wraps, "(gmb_string_alloc(_id), gmb_string_alloc(_t), gmb_string_alloc(_s), (gmb_double_t)_v); }\n");
            }
        }
        ind(c);
        sb_put(&c->out, "gmb_signal_on(");
        em_msg_str(c, (s->n_netargs > 0) ? s->net_args[0] : NULL);
        if (npar >= 5) { sb_put(&c->out, ", NULL, _gmb_sigcb_"); }
        else { sb_put(&c->out, ", _gmb_sigcb_"); }
        sb_ident(&c->out, h);
        if (npar >= 5) sb_put(&c->out, ");\n");
        else sb_put(&c->out, ", NULL);\n");
    }
}
