static int bf_m_abs(ctx_t* c, gmb_expr_t** a, int n){ if(n!=1)return 0; sb_put(&c->out,"fabs("); emit_num_operand(c,a[0]); sb_put(&c->out,")"); return 1; }
static int bf_m_sqr(ctx_t* c, gmb_expr_t** a, int n){ if(n!=1)return 0; sb_put(&c->out,"sqrt("); emit_num_operand(c,a[0]); sb_put(&c->out,")"); return 1; }
/* INT: floor verso -inf (parity IL: TokenKind.Int -> IlRuntimeFloor/ Math.Floor), NON tronca
 * verso zero (INT(-3.9) = -4). FIX/TRUNC restano tronca. */
static int bf_m_int(ctx_t* c, gmb_expr_t** a, int n){ if(n!=1)return 0; sb_put(&c->out,"floor((double)("); emit_num_operand(c,a[0]); sb_put(&c->out,"))"); return 1; }
static int is_byval_arr_param(ctx_t* c, const char* name);
static int bf_m_len(ctx_t* c, gmb_expr_t** a, int n){
    if(n!=1)return 0;
    /* LEN(bytes()) — CALL 0-arg su una var LISTA = il contenitore INTERO (array da
     * ReadAllBytes/ReadAllLines). Prima emetteva `(bytes).length` → C non compilabile
     * (§ FilesFullCoverage righe 53/55). */
    if (a[0] && a[0]->kind == GMB_EXPR_CALL && a[0]->nargs == 0 && a[0]->var) {
        var_t* cv = lookup_var(c, a[0]->var);
        if (cv && cv->gkind && gk_is_list(cv->gkind)) {
            sb_put(&c->out, "(gmb_double_t)gmb_list_count(");
            emit_ident(c, cv->name);
            sb_put(&c->out, ")");
            return 1;
        }
        /* LEN(arr()) — CALL 0-arg su una var ARRAY/MATRICE = l'array INTERO → lunghezza (_len).
         * (es. TimeSeriesFullCoverage: DIM rm() = TS.TSROLLMAD(s,3) : LEN(rm()); rr matrice). */
        if (cv && cv->is_array) {
            sb_put(&c->out, "(gmb_double_t)("); emit_arr_len_of(c, cv); sb_put(&c->out, ")");
            return 1;
        }
    }
    /* LEN(<call che ritorna gmb_list_t>) — AI.AGENTLIST/AGENTEVENTS/AI.LIST:
     * gmb_list_count(<call>). Prima emetteva `.length` su gmb_list_t → cc error
     * (gen_AI_AgentLoad: LEN(AI.AGENTLIST())). */
    if (a[0] && a[0]->kind == GMB_EXPR_CALL
        && (a[0]->tk == GMB_TOK_AiAgentList || a[0]->tk == GMB_TOK_AiAgentEvents
            || a[0]->tk == GMB_TOK_AiList || a[0]->tk == GMB_TOK_Keys || a[0]->tk == GMB_TOK_Values)) {
        sb_put(&c->out, "(gmb_double_t)gmb_list_count(");
        emit_expr(c, a[0]);
            sb_put(&c->out, ")");
        return 1;
    }
    /* LEN(rs("col")) / campo dinamico SQL (call che ritorna gmb_val_t) → gmb_val_length
     * (stringa: caratteri; lista: elementi; dizionario: chiavi). Prima emetteva
     * `(gmb_sql_current_val(...)).length` = `.length` su gmb_val_t → errore cc. */
    if (a[0] && a[0]->kind == GMB_EXPR_CALL && a[0]->var && a[0]->nargs == 1 && a[0]->args) {
        var_t* rsv = lookup_var(c, a[0]->var);
        if (rsv && rsv->sql_rs) {
            sb_put(&c->out, "(gmb_double_t)gmb_val_length(");
            emit_expr(c, a[0]);
            sb_put(&c->out, ")");
            return 1;
        }
    }
    /* LEN(<var JSON/ANY boxed>) → gmb_val_length (stringa: caratteri; lista: elementi; dizionario: chiavi). Prima `(g).length` su un
     * gmb_val_t: errore cc. */
    if (a[0] && a[0]->kind == GMB_EXPR_VAR && a[0]->var) {
        var_t* bv = lookup_var(c, a[0]->var);
        if (bv && bv->boxed_val && !bv->gkind && !bv->vclass[0] && !bv->is_array) {
            sb_put(&c->out, "(gmb_double_t)gmb_val_length(");
            emit_ident(c, bv->name);
            sb_put(&c->out, ")");
            return 1;
        }
    }
    /* LEN(<var lista>) → numero di elementi (parity IL/PCode/VMC; es. DIM r = RANGE(...)). */
    if (a[0] && a[0]->kind == GMB_EXPR_VAR && a[0]->var) {
        var_t* lv = lookup_var(c, a[0]->var);
        if (lv && lv->gkind && gk_is_list(lv->gkind)) {
            sb_put(&c->out, "(gmb_double_t)gmb_list_count(");
            emit_ident(c, lv->name);
            sb_put(&c->out, ")");
            return 1;
        }
        /* LEN(array nativo): DIM(N) → contatore `<var>_count` (dim_expr); DIM a = {…} →
         * `<var>_len` (emesso dal ramo DIM-literal). Prima: `(a).length` su un
         * gmb_double_t* → errore C (parity IL/PCode/VM-C LEN(array)).
         * PARAMETRO array: l'ABI passa il BOUND compagna `<param>__b0` (= ultimo indice,
         * len-1) → LEN = bound + 1 (parità IL/PCode/VM-C, bug LEN-Array-Parametro). */
        if (lv && lv->is_array && !lv->gkind && !lv->matrix) {
            if (is_byval_arr_param(c, lv->name) || lv->arr_byref) {
                sb_put(&c->out, "((gmb_double_t)(");
                sb_bound_var(&c->out, lv, 0);
                sb_put(&c->out, ") + 1)");
                return 1;
            }
            if (lv->dim_expr[0]) {
                sb_printf(&c->out, "(gmb_double_t)%s", lv->dim_expr);
                return 1;
            }
            sb_put(&c->out, "(gmb_double_t)");
            emit_ident(c, lv->name);
            sb_put(&c->out, "_len");
            return 1;
        }
    }
    /* LEN(<var boxed>.<membro>) — il membro è una chiave del dict (lista/stringa/dict):
     * lunghezza runtime via gmb_val_length (parity VM/C case LEN su GMB_OBJ_DICT; es.
     * TRADING.PORTFOLIO LEN(x.Weights) dove x è PortfolioResult boxed). */
    if (a[0] && a[0]->kind == GMB_EXPR_VAR && a[0]->var) {
        const char* dot = strchr(a[0]->var, '.');
        if (dot && dot != a[0]->var) {
            char base[160]; size_t bl = (size_t)(dot - a[0]->var);
            if (bl < sizeof(base)) {
                memcpy(base, a[0]->var, bl); base[bl] = 0;
                var_t* bv = lookup_var(c, base);
                if (bv && bv->boxed_val && !bv->gkind && !bv->vclass[0]) {
                    sb_put(&c->out, "((gmb_double_t)gmb_val_length(gmb_dict_get(gmb_val_as_dict(");
                    emit_ident(c, bv->name);
                    sb_printf(&c->out, "), \"%s\")))", dot + 1);
                    return 1;
                }
            }
        }
    }
    /* LEN() di una lista del LEDGER: le funzioni `*_val` del runtime restituiscono un gmb_val_t, la
     * cui lunghezza si legge con gmb_list_count() (il membro .length è delle liste dell'emitter).
     * Dispatch per TokenKind (regola d'oro), non per lexeme. */
    if (a[0] && (a[0]->tk == GMB_TOK_Accounts || a[0]->tk == GMB_TOK_Balance || a[0]->tk == GMB_TOK_Register
                 || a[0]->tk == GMB_TOK_Get)) {
        sb_put(&c->out, "((gmb_double_t)gmb_list_count(");
        emit_expr(c, a[0]);
        sb_put(&c->out, "))");
        return 1;
    }
    /* LEN(<stringa>) — numero di CARATTERI (code point): "é"=1, "😀"=1 (4 byte).
     * Prima si contavano i byte (`.length`) o le unità UTF-16: vedi (solved) LEN-UTF8.
     * CAMPO DBF late-binding (IMPORT DBF): l'espressione è un gmb_val_t, non una
     * gmb_string_t → va convertita, altrimenti il C generato non compila
     * ("passing gmb_val_t to gmb_str_t_len": LEN(DESC) in DbfMemoCrud.bas). */
    if (ensure_dbf_field_var(c, a[0])) {
        sb_put(&c->out,"((gmb_double_t)gmb_str_t_len(gmb_val_to_string("); emit_expr(c,a[0]); sb_put(&c->out,")))"); return 1;
    }
    sb_put(&c->out,"((gmb_double_t)gmb_str_t_len("); emit_expr(c,a[0]); sb_put(&c->out,"))"); return 1; }
/* LENB(<expr>) — BYTE UTF-8 (LEN conta i CARATTERI). Argomento non stringa → -1, come le
 * altre gambe (parità dei parametri: prima un numero dava un errore di compilazione C). */
static int bf_m_lenb(ctx_t* c, gmb_expr_t** a, int n){
    if (n != 1 || !a[0]) return 0;
    if (etype(c, a[0]) == TY_STR) {
        sb_put(&c->out, "((gmb_double_t)gmb_str_bytes("); emit_expr(c, a[0]); sb_put(&c->out, "))");
    } else {
        sb_put(&c->out, "(-1.0)");
    }
    return 1;
}
/* LEN() di una lista del LEDGER (variante dedicata, tenuta per chiarezza del dominio). */
static int ld_len_val(ctx_t* c, gmb_expr_t** a, int n)
{
    if (n < 1 || !a[0]) return 0;
    sb_put(&c->out, "((gmb_double_t)gmb_list_count(");
    emit_expr(c, a[0]);
    sb_put(&c->out, "))");
    return 1;
}
