                    sb_ident(&c->out, mf->cls_owner);
                    sb_put(&c->out, "_");
                    sb_ident(&c->out, mf->stmt->func_name);
                    sb_put(&c->out, "(");
                    if (bv) { sb_put(&c->out, "&"); emit_ident(c, bv->name); }
                    else sb_put(&c->out, "self");
                    for (int i = 0; i < nargs; i++) { sb_put(&c->out, ", "); emit_param_arg(c, mf, i, args[i]); }
