static void st_add_handler(ctx_t* c, gmb_stmt_t* s) {
{
        const char* evn = NULL;
        if (s->channel && s->channel->kind == GMB_EXPR_VAR && s->channel->var) {
            const char* dot = strchr(s->channel->var, '.');
            evn = dot && dot[1] ? dot + 1 : s->channel->var;
        }
        const char* hn = (s->send_value && s->send_value->kind == GMB_EXPR_VAR) ? s->send_value->var : NULL;
        if (!evn || !hn) { c99_fail(c, s->line, "ADD/REMOVE HANDLER: evento o handler non risolvibile"); return; }
        ind(c); sb_printf(&c->out, "gmb_event_%s(\"%s\", (void(*)(void))gmb_user_",
                          s->kind == GMB_STMT_ADD_HANDLER ? "add" : "remove", evn);
        sb_ident(&c->out, hn); sb_put(&c->out, ");\n");
        return;
    }
}

static void st_raise_event(ctx_t* c, gmb_stmt_t* s) {
{
        const char* evn = (s->proc_name && s->proc_name->kind == GMB_EXPR_VAR) ? s->proc_name->var : NULL;
        if (!evn) { c99_fail(c, s->line, "RAISE EVENT: nome evento non risolvibile"); return; }
        ind(c); sb_printf(&c->out, "for (gmb_event_handler_t* __eh = gmb_event_first(\"%s\"); __eh; __eh = gmb_event_next(__eh, \"%s\")) {\n", evn, evn);
        c->indent++;
        ind(c); sb_put(&c->out, "((void(*)(");
        if (s->n_go_args == 0) sb_put(&c->out, "void");
        for (int i = 0; i < s->n_go_args; i++) {
            if (i) sb_put(&c->out, ", ");
            sb_put(&c->out, etype(c, s->go_args[i]) == TY_STR ? "gmb_string_t" : "gmb_double_t");
        }
        sb_put(&c->out, "))__eh->fn)(");
        for (int i = 0; i < s->n_go_args; i++) {
            if (i) sb_put(&c->out, ", ");
            emit_expr(c, s->go_args[i]);
        }
        sb_put(&c->out, ");\n");
        c->indent--;
        ind(c); sb_put(&c->out, "}\n");
        return;
    }
}

typedef struct { gmb_stmt_kind_t kind; void (*fn)(ctx_t* c, gmb_stmt_t* s); } ST_EMIT_TBL_row;
static void st_json_save(ctx_t* c, gmb_stmt_t* s);
/* Confronto case-insensitive senza <ctype.h> (il file non lo include). */
static int json_open_eq_ci(const char* a, const char* b) {
    if (!a || !b) return 0;
    while (*a && *b) {
        char ca = *a, cb = *b;
        if (ca >= 'A' && ca <= 'Z') ca = (char)(ca - 'A' + 'a');
        if (cb >= 'A' && cb <= 'Z') cb = (char)(cb - 'A' + 'a');
        if (ca != cb) return 0;
        a++; b++;
    }
    return *a == 0 && *b == 0;
}

/* Moda di `JSON OPEN ... FOR <moda>` nota A COMPILE-TIME → lettera canonica per gmb_file_open.
 * Canone C# (`common/Parser/Parser.Stmt.Json.cs`, `ParseJsonOpenStatement`): la moda e' uno
 * StringExpr oppure un VariableExpr, e viene mappata PER NOME:
 *   READ/INPUT/R → Input ("r") · WRITE/OUTPUT/W → Output ("w") · APPEND/A → Append ("a").
 * Un identificatore NUDO (es. `FOR READ`) NON e' una variabile: e' una costante di modo, e
 * trattarlo come espressione produceva `gmb_double_to_string(READ)` (il valore numerico → "0"),
 * che cadeva nel default "w": il file veniva aperto in SCRITTURA (troncamento) e l'`INPUT #`
 * successivo leggeva vuoto (JsonFullTests.bas, solo gamba C99Native: "Utente: " vuoto).
 * Ritorna NULL quando la moda e' davvero dinamica (variabile utente) → resta il percorso
 * runtime preesistente. */
static const char* json_open_mode_of(const gmb_expr_t* e) {
    if (!e) return NULL;
    const char* nm = (e->kind == GMB_EXPR_STR) ? e->str
                   : (e->kind == GMB_EXPR_VAR) ? e->var : NULL;
    if (!nm || !nm[0]) return NULL;
    if (json_open_eq_ci(nm, "READ") || json_open_eq_ci(nm, "INPUT") || json_open_eq_ci(nm, "R")) return "r";
    if (json_open_eq_ci(nm, "WRITE") || json_open_eq_ci(nm, "OUTPUT") || json_open_eq_ci(nm, "W")) return "w";
    if (json_open_eq_ci(nm, "APPEND") || json_open_eq_ci(nm, "A")) return "a";
    /* stringa letterale non riconosciuta: default storico "w" (il C# solleva errore; qui si
     * resta permissivi). Un IDENTIFICATORE non-modo resta invece dinamico (NULL). */
    return (e->kind == GMB_EXPR_STR) ? "w" : NULL;
}

/* JSON OPEN file$ FOR mode$ AS #h — apre il file col runtime condiviso (gmb_file_open,
 * come st_open) e scrive l'handle nella variabile `h`. La modalità arriva come STRINGA
 * ("WRITE"/"READ"/"APPEND") o come identificatore nudo (READ/WRITE/APPEND) → "w"/"r"/"a".
 * Prima: st_noop (silenzioso). */
static void st_json_open(ctx_t* c, gmb_stmt_t* s) {
    if (!s->channel || !s->win_name) return;
    const char* __mode_lit = json_open_mode_of(s->send_value);
    ind(c);
    sb_put(&c->out, "{ gmb_string_t __fp = ");
    emit_str_operand(c, s->channel);
    if (__mode_lit) {
        /* moda risolta a compile-time: nessun __fm, la lettera e' una costante C. */
        sb_printf(&c->out, "; const char* __m = \"%s\"; gmb_int_t __fh = (gmb_int_t)(", __mode_lit);
    } else {
    sb_put(&c->out, "; gmb_string_t __fm = ");
    if (s->send_value) emit_str_operand(c, s->send_value);
    else sb_put(&c->out, "gmb_string_alloc(\"WRITE\")");
    /* L'handle si passa via TEMPORANEO gmb_int_t e si assegna alla variabile: `&h` diretto
     * falliva se `h` era dichiarata double (gmb_file_open scriveva 8 byte sul posto sbagliato
     * → h restava 0 → il PRINT #h scriveva su un handle non valido, file vuoto). */
    /* Canone IL: la variabile È il file number → si parte dal suo valore corrente (0 se
     * appena DIMmata) e gmb_file_open lo onora (non lo ri-alloca). Un `DIM h` + `JSON OPEN
     * AS #h` lascia h=0 come il/pcode/vmc/c99 (bug C99Native-JSON-OPEN-Handle-Diverge). */
    /* 'I'/'i' incluso: "INPUT" e' una moda di LETTURA (canone C#, prima cadeva in "w"). */
    sb_put(&c->out, "; const char* __m = (__fm.data && (__fm.data[0] == 'R' || __fm.data[0] == 'r' || __fm.data[0] == 'I' || __fm.data[0] == 'i')) ? \"r\" : ((__fm.data && (__fm.data[0] == 'A' || __fm.data[0] == 'a')) ? \"a\" : \"w\"); gmb_int_t __fh = (gmb_int_t)(");
    }
    emit_ident(c, s->win_name);
    sb_put(&c->out, "); gmb_file_open(__fp, __m, &__fh); ");
    emit_ident(c, s->win_name);
    sb_put(&c->out, " = (gmb_double_t)__fh; }\n");
    /* ricorda che questo canale e' JSON: INPUT #h leggera' l'intero documento (gmb_file_read_json), non una riga CSV */
    if (c->n_json_chans < 16) snprintf(c->json_chans[c->n_json_chans++], 64, "%s", s->win_name);
}

static void st_json_writevalue(ctx_t* c, gmb_stmt_t* s);
static void st_json_open(ctx_t* c, gmb_stmt_t* s);
static void st_json_writesection(ctx_t* c, gmb_stmt_t* s);
/* SEEK n, pos — COMANDO legacy, posizione 1-BASED (`SEEK 1, 1` = inizio). Emette
 * gmb_file_seek(handle, pos - 1, 0), con lo stesso handle-per-numero-di-file usato da OPEN
 * (emit_handle) e la stessa formula del C99 C# (C99CodeEmitter: (pos) - 1).
 * Prima lo statement non era nemmeno PARSATO (GMB_TOK_Seek stava in gmb_tk_rem_vari_toks):
 * veniva ignorato in silenzio, quindi dopo `SEEK 1, 3` la gamba C99Native leggeva 0
 * (§ MiniTests/io/io_misc.bas, dove IL/PCode/VMC leggono 2). */
static void st_seek(ctx_t* c, gmb_stmt_t* s) {
    if (!s->file_num) return;
    ind(c);
    sb_put(&c->out, "gmb_file_seek(");
    emit_handle(c, s->file_num, s->line);
    if (s->file_pos) {
        sb_put(&c->out, ", (long)((");
        emit_expr(c, s->file_pos);
        sb_put(&c->out, ") - 1), 0);\n");
    } else {
        sb_put(&c->out, ", 0, 0);\n");
    }
}

/* IO.WRITEBYTES(path, buf()): scrittura byte-esatta di un array BYTE.
 * Nel C99 gli array del linguaggio sono double[] (come per MMAPWRITEBYTES), quindi si passa
 * puntatore + lunghezza alla funzione condivisa del runtime (§0bis). */
int emit_bf_writebytes(ctx_t* c, const char* name, const char* ns, gmb_tokenkind_t tk,
                       gmb_expr_t** args, int nargs, int line) {
    (void)name; (void)ns; (void)tk;
    if (nargs != 2 || !args[0] || !args[1] || !args[1]->var) {
        c99_fail(c, line, "IO.WRITEBYTES richiede (path, array DIM di byte) (backend C99Native)");
        return 1;
    }
    var_t* av = lookup_var(c, args[1]->var);
    if (!av || !av->is_array) {
        c99_fail(c, line, "IO.WRITEBYTES: '%s' non e' un array DIM", args[1]->var);
        return 1;
    }
    sb_put(&c->out, "gmb_write_all_bytes_f64((");
    emit_str_operand(c, args[0]);
    sb_put(&c->out, ").data, (const double*)");
    emit_var_ref(c, av);
    sb_put(&c->out, ", (int)(");
    emit_arr_len_of(c, av);
    sb_put(&c->out, "))");
    return 1;
}

/* MEMORYMAP comandi (2026-09-15): MMAPPOKE / MMAPWRITEBYTES.
 * L'array sorgente di WRITEBYTES è gmb_int_t[] (BYTE nativo C) → serve
 * gmb_mmap_write_bytes_i64 (conversione elemento→byte), mai un cast diretto. */
static void st_mmap_poke(ctx_t* c, gmb_stmt_t* s) {
    ind(c);
    sb_put(&c->out, "gmb_mmap_poke((int64_t)(");
    emit_expr(c, s->file_num);
    sb_put(&c->out, "), (int64_t)(");
    if (s->file_pos) emit_expr(c, s->file_pos); else sb_put(&c->out, "0");
    sb_put(&c->out, "), (int)(");
    if (s->nprint >= 1 && s->print_args && s->print_args[0]) emit_expr(c, s->print_args[0]);
    else sb_put(&c->out, "0");
    sb_put(&c->out, "));\n");
}
static void st_mmap_writebytes(ctx_t* c, gmb_stmt_t* s) {
    /* `buf()` arriva come CALL con var (nargs 0) o VAR: entrambi hanno ->var. */
    if (!s->print_args || s->nprint < 1 || !s->print_args[0]->var) {
        c99_fail(c, s->line, "MMAPWRITEBYTES: l'array sorgente deve essere una variabile BYTE()");
        return;
    }
    var_t* av = lookup_var(c, s->print_args[0]->var);
    if (!av || !av->is_array) {
        c99_fail(c, s->line, "MMAPWRITEBYTES: '%s' non e' un array DIM", s->print_args[0]->var);
        return;
    }
    ind(c);
    sb_put(&c->out, "gmb_mmap_write_bytes_f64((int64_t)(");
    emit_expr(c, s->file_num);
    sb_put(&c->out, "), (int64_t)(");
    if (s->file_pos) emit_expr(c, s->file_pos); else sb_put(&c->out, "0");
    sb_put(&c->out, "), (const double*)");
    emit_var_ref(c, av);
    sb_put(&c->out, ", (int)(");
    if (s->nprint >= 2 && s->print_args[1]) emit_expr(c, s->print_args[1]);
    else emit_arr_len_of(c, av);
    sb_put(&c->out, "));\n");
}

/* CPRINT (flag=1): come PRINT ma forzato su console (stdout), non TUI/gfx. */
static void st_print(ctx_t* c, gmb_stmt_t* s) {
    int cp = (s->flag == 1);
    if (cp) { ind(c); sb_put(&c->out, "gmb_print_force_console(1);\n"); }
    st_print_core(c, s);
    if (cp) { ind(c); sb_put(&c->out, "gmb_print_force_console(0);\n"); }
}

